// Gerado por scripts/build.mjs. Não edite à mão: edite recipes/ e videos/ e rode npm run build.
window.CADERNO = {"recipes":[{"id":"arroz-de-sushi","title":"Arroz de sushi (shari)","category":"Sushi","description":"Arroz japonês de grão curto na panela comum, começando com água gelada e temperado com vinagre de sushi. Rende cerca de 1,1 kg.","servings":4,"scale":true,"ingredients":[{"amount":400,"id":"1","name":"arroz japonês de grão curto","unit":"g"},{"amount":460,"id":"2","name":"água gelada (480 ml em panela fina)","unit":"ml"},{"amount":1,"id":"3","name":"pedaço de kombu, ~5 cm (opcional)","unit":""},{"amount":100,"id":"4","name":"Mizkan Sushi Seasoning (すし酢)","unit":"ml"}],"steps":[{"content":"Lave {1} em água fria da torneira, esfregando de leve e trocando a água logo, até sair quase transparente (4–5 vezes). Escorra bem.","timer":0,"title":"Lavar"},{"content":"Coloque o arroz na panela com {2} e {3}. Deixe de molho com o fogo desligado.","timer":1800,"title":"Deixar de molho"},{"content":"Retire o kombu. Se a tampa não vedar bem, coloque papel-alumínio ou um pano de prato (pontas dobradas para cima, longe da chama) entre a panela e a tampa.","timer":0,"title":"Vedar a panela"},{"content":"Fogo médio-alto, tampado, até ferver. Com água gelada leva uns 8–10 minutos; você percebe pelo vapor e pelo barulho da tampa.","timer":540,"title":"Levar à fervura"},{"content":"Menor boca, fogo mínimo absoluto (de preferência com frigideira de ferro ou difusor por baixo). Não abra a tampa nem mexa. Se sentir cheiro de queimado, desligue.","timer":750,"title":"Cozinhar no mínimo"},{"content":"Desligue e deixe tampado, sem abrir, para o vapor terminar de cozinhar o grão.","timer":900,"title":"Descansar"},{"content":"Passe o arroz de uma vez para um bowl largo de madeira ou vidro, sem raspar o fundo. Regue na hora uns 80% de {4}, espalhando com a espátula como guia.","timer":0,"title":"Temperar quente"},{"content":"Misture com cortes verticais da espátula, sem amassar nem mexer em círculos, abanando ao mesmo tempo para dar brilho. Prove e complete o tempero.","timer":120,"title":"Misturar e abanar"},{"content":"Espalhe o arroz, cubra com pano úmido e espere chegar à temperatura do corpo antes de montar. Use em até 3–4 horas e nunca leve à geladeira.","timer":900,"title":"Esfriar"}],"notes":"Sem sushi seasoning pronto: 80 ml de vinagre de arroz, 2½ colheres de sopa de açúcar e 1½ colher de chá de sal. Nigiri mais firme: ~440 ml de água; maki mais macio: ~480 ml. Comece 1h30 antes de montar. Rende 8–10 rolos de maki ou 50–60 nigiris.","images":[],"updatedAt":"2026-11-01T09:50:00.000Z"},{"id":"arroz-no-arado","title":"Arroz no arado (paella caipira)","category":"Pratos","description":"Arroz com seis carnes, linguiças, legumes e amendoim, feito no disco de arado para servir muita gente.","servings":20,"yieldLabel":"porções","scale":true,"ingredients":[{"amount":"","id":"1","name":"## Carnes","unit":""},{"amount":400,"id":"2","name":"contrafilé em cubos","unit":"g"},{"amount":400,"id":"3","name":"copa lombo em cubos","unit":"g"},{"amount":400,"id":"4","name":"filé de peito de frango em cubos","unit":"g"},{"amount":"","id":"5","name":"## Tempero das carnes","unit":""},{"amount":1,"id":"6","name":"sal","unit":"tsp"},{"amount":1,"id":"7","name":"alho triturado","unit":"tsp"},{"amount":1,"id":"8","name":"pimenta-do-reino moída e pimenta calabresa","unit":"pinch"},{"amount":2,"id":"9","name":"alecrim desidratado","unit":"pinch"},{"amount":3,"id":"10","name":"folhas de louro","unit":""},{"amount":2,"id":"11","name":"sálvia desidratada","unit":"pinch"},{"amount":"","id":"12","name":"## Para o arado","unit":""},{"amount":"","id":"13","name":"½ copo (americano) de óleo","unit":""},{"amount":400,"id":"14","name":"bacon sem pele em cubinhos","unit":"g"},{"amount":400,"id":"15","name":"linguiça toscana sem pele, esmagada","unit":"g"},{"amount":400,"id":"16","name":"linguiça fina defumada sem pele, esmagada","unit":"g"},{"amount":400,"id":"17","name":"linguiça calabresa em cubinhos","unit":"g"},{"amount":1,"id":"18","name":"cebola em tiras","unit":"kg"},{"amount":1.2,"id":"19","name":"tomate em pedaços grandes (+1 tomate para decorar)","unit":"kg"},{"amount":2,"id":"20","name":"talos de alho-poró em rodelas finas (200 g)","unit":""},{"amount":2,"id":"21","name":"maços de cheiro-verde (salsinha e cebolinha) picados","unit":""},{"amount":2,"id":"22","name":"latas de milho-verde escorrido","unit":""},{"amount":2,"id":"23","name":"sal","unit":"tsp"},{"amount":2,"id":"24","name":"sachês de tempero pronto para carne","unit":""},{"amount":2,"id":"25","name":"tabletes de caldo de galinha","unit":""},{"amount":2,"id":"26","name":"arroz agulhinha cozido","unit":"kg"},{"amount":300,"id":"27","name":"amendoim torrado sem pele (com ou sem sal)","unit":"g"},{"amount":"","id":"28","name":"azeite a gosto","unit":""}],"steps":[{"content":"Tempere o contrafilé, a copa lombo e o frango com o sal, o alho, as pimentas, o alecrim, o louro e a sálvia. Reserve.","timer":0,"title":"Temperar as carnes"},{"content":"Aqueça o óleo no arado. Frite o bacon por 4–5 minutos, até dourar, e afaste para a lateral. Repita com a linguiça toscana, depois a linguiça fina, a calabresa e, por fim, as carnes temperadas, sempre afastando para a lateral.","timer":300,"title":"Fritar as carnes por etapas"},{"content":"No óleo que ficou no centro, refogue a cebola até murchar. Junte o tomate, o alho-poró, parte do cheiro-verde, o milho, o sal, o tempero pronto e o caldo de galinha. Mexa por 2 minutos.","timer":120,"title":"Refogar os legumes"},{"content":"Misture os legumes com todas as carnes e acrescente o arroz cozido em duas etapas, mexendo bem.","timer":0,"title":"Juntar o arroz"},{"content":"Salpique parte do amendoim e misture. Decore o centro com um tomate cortado em 8, o restante do amendoim e do cheiro-verde e um fio de azeite. Apague o fogo e sirva.","timer":0,"title":"Finalizar"}],"notes":"Feito no disco de arado sobre fogo, mas dá para adaptar numa panela paella grande ou numa frigideira larga, em levas.","images":[{"src":"images/arroz-no-arado/01.jpg","caption":"Arroz no arado pronto."}],"source":"Arroz_de_Arado_-_Paella_Caipira.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"rub-jacks-old-south","title":"BBQ rub Jack's Old South","category":"Temperos","description":"Rub doce e defumado para porco e costela: açúcar mascavo, páprica doce, sal kosher e pimentas.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":0.25,"id":"1","name":"açúcar mascavo","unit":"cup"},{"amount":0.25,"id":"2","name":"páprica doce","unit":"cup"},{"amount":0.25,"id":"3","name":"sal kosher","unit":"cup"},{"amount":3,"id":"4","name":"pimenta-do-reino","unit":"tbsp"},{"amount":2,"id":"5","name":"alho em pó","unit":"tsp"},{"amount":2,"id":"6","name":"cebola em pó","unit":"tsp"},{"amount":1,"id":"7","name":"pimenta-caiena","unit":"tsp"},{"amount":1,"id":"8","name":"manjericão seco","unit":"tsp"}],"steps":[{"content":"Combine todos os ingredientes e misture bem. Guarde em pote fechado.","timer":0,"title":"Misturar"}],"notes":"","images":[],"source":"BBB_Temperos_Miron_Mixon.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"beijo-de-mulata","title":"Beijo de mulata","category":"Doces","description":"Bolinhos fritos de massa com pinga, banhados em calda quente de chocolate e passados no coco ralado.","servings":1,"yieldLabel":"receita","scale":false,"ingredients":[{"amount":"","id":"1","name":"## Massa","unit":""},{"amount":3,"id":"2","name":"ovos","unit":""},{"amount":1,"id":"3","name":"cálice de pinga","unit":""},{"amount":7,"id":"4","name":"açúcar","unit":"tbsp"},{"amount":1,"id":"5","name":"manteiga","unit":"tbsp"},{"amount":0.5,"id":"6","name":"fermento em pó","unit":"tbsp"},{"amount":"","id":"7","name":"farinha de trigo até dar ponto de enrolar","unit":""},{"amount":"","id":"8","name":"óleo para fritar","unit":""},{"amount":"","id":"9","name":"## Calda","unit":""},{"amount":2,"id":"10","name":"açúcar","unit":"cup"},{"amount":2,"id":"11","name":"chocolate do padre (chocolate em pó)","unit":"cup"},{"amount":2,"id":"12","name":"leite","unit":"cup"},{"amount":"","id":"13","name":"coco ralado para passar","unit":""}],"steps":[{"content":"Misture os ovos, a pinga, o açúcar, a manteiga e o fermento. Junte farinha aos poucos até a massa dar ponto de enrolar.","timer":0,"title":"Fazer a massa"},{"content":"Enrole em cordões e corte como nhoque. Frite em óleo quente até dourar.","timer":0,"title":"Cortar e fritar"},{"content":"Leve ao fogo o açúcar, o chocolate e o leite, mexendo até formar uma calda.","timer":0,"title":"Fazer a calda"},{"content":"Passe os bolinhos na calda ainda quente e depois no coco ralado.","timer":0,"title":"Finalizar"}],"notes":"","images":[],"source":"Beijo_de_Mulata.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"bolinho-de-feijoada","title":"Bolinho de feijoada","category":"Salgados","description":"Massa de feijão-preto com carnes, engrossada com farinha de mandioca, recheada com couve refogada e empanada.","servings":1,"yieldLabel":"receita","scale":false,"ingredients":[{"amount":"","id":"1","name":"## Feijoada","unit":""},{"amount":2,"id":"2","name":"água","unit":"l"},{"amount":500,"id":"3","name":"feijão-preto","unit":"g"},{"amount":100,"id":"4","name":"carne-seca dessalgada em cubinhos","unit":"g"},{"amount":100,"id":"5","name":"lombo defumado em cubinhos","unit":"g"},{"amount":100,"id":"6","name":"costelinha dessalgada ou defumada","unit":"g"},{"amount":1,"id":"7","name":"linguiça calabresa em cubos","unit":""},{"amount":1,"id":"8","name":"paio em cubos","unit":""},{"amount":3,"id":"9","name":"folhas de louro","unit":""},{"amount":"","id":"10","name":"## Massa","unit":""},{"amount":3,"id":"11","name":"azeite","unit":"tbsp"},{"amount":3,"id":"12","name":"dentes de alho","unit":""},{"amount":200,"id":"13","name":"farinha de mandioca fina, sem torrar","unit":"g"},{"amount":1,"id":"14","name":"polvilho azedo","unit":"tbsp"},{"amount":"","id":"15","name":"## Recheio de couve","unit":""},{"amount":2,"id":"16","name":"maços de couve cortada bem fininha","unit":""},{"amount":250,"id":"17","name":"bacon em cubinhos","unit":"g"},{"amount":2,"id":"18","name":"dentes de alho","unit":""},{"amount":"","id":"19","name":"azeite","unit":""},{"amount":"","id":"20","name":"## Para empanar e servir","unit":""},{"amount":"","id":"21","name":"farinha de rosca","unit":""},{"amount":"","id":"22","name":"óleo para fritar","unit":""},{"amount":"","id":"23","name":"gomos de laranja","unit":""},{"amount":"","id":"24","name":"torresmo","unit":""},{"amount":"","id":"25","name":"batida de limão","unit":""}],"steps":[{"content":"Na panela de pressão, coloque a água, o feijão, as carnes e o louro. Cozinhe por cerca de 1 hora, contando depois que pegar pressão.","timer":3600,"title":"Cozinhar a feijoada"},{"content":"Retire o louro e bata o feijão com as carnes até virar um creme grosso.","timer":0,"title":"Bater o feijão"},{"content":"Aqueça o azeite numa panela grande, doure o alho e refogue o feijão batido. Acerte o sal. Acrescente a farinha de mandioca aos poucos, sem parar de mexer, até engrossar e soltar do fundo.","timer":0,"title":"Engrossar a massa"},{"content":"Retire do fogo e deixe esfriar. Junte o polvilho e misture até a massa ficar homogênea.","timer":0,"title":"Esfriar e dar liga"},{"content":"Numa frigideira, doure o bacon com o alho, junte a couve e refogue por 2 minutos.","timer":120,"title":"Refogar a couve"},{"content":"Abra pequenas porções de massa na mão, coloque 1 colher de chá de couve, feche em bolinhos e achate levemente.","timer":0,"title":"Modelar"},{"content":"Passe na farinha de rosca e frite em óleo quente até dourar.","timer":0,"title":"Empanar e fritar"},{"content":"Sirva com gomos de laranja, torresmo e uma batidinha de limão.","timer":0,"title":"Servir"}],"notes":"O passo de bater o feijão está implícito na receita original, que fala em \"refogar o feijão batido\".","images":[],"source":"Bolinho_de_feijoada.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"bolo-de-banana-e-castanhas","title":"Bolo de banana e castanhas","category":"Bolos","description":"Bolo sem farinha de trigo: banana madura, farinha de amêndoas, aveia, castanha-do-pará e frutas secas.","servings":1,"yieldLabel":"fôrma","scale":true,"ingredients":[{"amount":3,"id":"1","name":"bananas pequenas bem maduras","unit":""},{"amount":4,"id":"2","name":"óleo de coco","unit":"tbsp"},{"amount":1,"id":"3","name":"canela em pó","unit":"tbsp"},{"amount":4,"id":"4","name":"ovos","unit":""},{"amount":1,"id":"5","name":"açúcar mascavo (+ um pouco para polvilhar)","unit":"tbsp"},{"amount":1,"id":"6","name":"farinha de amêndoas","unit":"cup"},{"amount":1,"id":"7","name":"aveia em flocos","unit":"cup"},{"amount":1,"id":"8","name":"fermento em pó","unit":"tbsp"},{"amount":10,"id":"9","name":"castanhas-do-pará","unit":""},{"amount":20,"id":"10","name":"uvas-passas","unit":""},{"amount":6,"id":"11","name":"damascos secos","unit":""},{"amount":0.5,"id":"12","name":"água","unit":"cup"}],"steps":[{"content":"No liquidificador, bata as bananas, o óleo de coco, a canela, os ovos, o açúcar e a água.","timer":0,"title":"Bater"},{"content":"Transfira para uma tigela e misture com colher ou batedor a farinha de amêndoas, a aveia e as frutas secas picadas (cerca de 8 castanhas, 6 damascos e 20 passas). Por último, o fermento.","timer":0,"title":"Misturar"},{"content":"Despeje numa fôrma untada, polvilhe açúcar mascavo e as castanhas restantes por cima. Asse por 35 minutos a 200 °C.","timer":2100,"title":"Assar"}],"notes":"","images":[],"source":"Bolo_de_Bananas_e_Castanhas.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"bolo-de-cenoura","title":"Bolo de cenoura com cobertura de chocolate","category":"Bolos","description":"O clássico do Panelinha: massa batida no liquidificador e calda de chocolate que endurece por cima.","servings":1,"yieldLabel":"fôrma 30 × 20 cm","scale":true,"ingredients":[{"amount":360,"id":"1","name":"cenoura descascada (cerca de 3 médias)","unit":"g"},{"amount":4,"id":"2","name":"ovos em temperatura ambiente","unit":""},{"amount":1,"id":"3","name":"óleo","unit":"cup"},{"amount":1.5,"id":"4","name":"açúcar","unit":"cup"},{"amount":2,"id":"5","name":"farinha de trigo","unit":"cup"},{"amount":1,"id":"6","name":"fermento em pó","unit":"tbsp"},{"amount":1,"id":"7","name":"sal","unit":"pinch"},{"amount":"","id":"8","name":"manteiga e farinha para untar","unit":""},{"amount":"","id":"9","name":"## Cobertura","unit":""},{"amount":0.5,"id":"10","name":"chocolate em pó 50% cacau","unit":"cup"},{"amount":0.333,"id":"11","name":"açúcar","unit":"cup"},{"amount":1,"id":"12","name":"manteiga","unit":"tbsp"},{"amount":0.333,"id":"13","name":"água","unit":"cup"}],"steps":[{"content":"Preaqueça o forno a 180 °C. Unte com manteiga uma fôrma de 30 × 20 cm e polvilhe farinha, batendo para tirar o excesso.","timer":0,"title":"Preparar o forno e a fôrma"},{"content":"Numa tigela, peneire a farinha, o sal e o fermento. Reserve.","timer":0,"title":"Peneirar os secos"},{"content":"Corte as cenouras em rodelas e bata no liquidificador com o óleo, os ovos (quebre um a um numa tigelinha antes) e o açúcar, por cerca de 5 minutos, até ficar liso.","timer":300,"title":"Bater os líquidos"},{"content":"Transfira para uma tigela grande e adicione os secos em 3 etapas, peneirando, misturando delicadamente com um batedor de arame.","timer":0,"title":"Misturar"},{"content":"Leve ao forno por cerca de 45 minutos, até um palito sair limpo.","timer":2700,"title":"Assar"},{"content":"Deixe esfriar 15 minutos. O bolo deve estar morno quando receber a cobertura.","timer":900,"title":"Amornar"},{"content":"Numa panela pequena, junte o chocolate, o açúcar, a manteiga e a água. Leve ao fogo médio mexendo até ferver, e mexa por mais 2 minutos, até formar bolhas grandes e engrossar.","timer":120,"title":"Fazer a cobertura"},{"content":"Desligue e mexa com espátula por cerca de 2 minutos, até parar de ferver. Isso evita que a calda escorra.","timer":120,"title":"Mexer fora do fogo"},{"content":"Regue o bolo e espalhe rápido. Deixe esfriar até a superfície endurecer antes de servir.","timer":0,"title":"Cobrir"}],"notes":"Funciona também numa fôrma redonda de 24 cm com furo no meio, com o mesmo tempo de forno. Dica: corte o bolo na assadeira antes da calda, para servir mais fácil.","images":[],"source":"Bolo_Cenoura_Panelinha.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"bolo-de-fuba-sem-gluten","title":"Bolo de fubá sem glúten e sem lactose","category":"Bolos","description":"Bolo de fubá com farinha de arroz, leite de coco e coco ralado. Fácil e pronto em 50 minutos.","servings":12,"yieldLabel":"fatias","scale":true,"ingredients":[{"amount":4,"id":"1","name":"ovos inteiros","unit":""},{"amount":1.5,"id":"2","name":"açúcar demerara","unit":"cup"},{"amount":2,"id":"3","name":"fubá","unit":"cup"},{"amount":3,"id":"4","name":"farinha de arroz (rasas)","unit":"tbsp"},{"amount":0.5,"id":"5","name":"óleo de milho ou girassol","unit":"cup"},{"amount":1,"id":"6","name":"leite de coco","unit":"cup"},{"amount":1,"id":"7","name":"fermento em pó","unit":"tbsp"},{"amount":3,"id":"8","name":"coco ralado","unit":"tbsp"},{"amount":"","id":"9","name":"óleo e farinha de arroz para untar","unit":""}],"steps":[{"content":"Bata os ovos, o açúcar e o óleo até obter um creme homogêneo.","timer":0,"title":"Bater o creme"},{"content":"Numa tigela, misture o fubá, a farinha de arroz, o coco ralado e o fermento. Junte ao creme, adicione o leite de coco e incorpore.","timer":0,"title":"Misturar os secos"},{"content":"Unte uma fôrma de 23 cm com óleo e farinha de arroz, despeje a massa e asse em forno preaquecido a 180 °C por cerca de 35 minutos.","timer":2100,"title":"Assar"}],"notes":"Tire do forno ainda úmido: ele seca um pouco depois de frio.","images":[{"src":"images/bolo-de-fuba-sem-gluten/01.jpg","caption":"Bolo de fubá pronto."}],"source":"Bolo_Fuba_sem_lactose_gluten.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"bolo-de-jabuticaba","title":"Bolo de jabuticaba","category":"Bolos","description":"Jabuticabas inteiras batidas com ovos, açúcar e óleo. Massa simples de liquidificador em fôrma de pudim.","servings":1,"yieldLabel":"fôrma","scale":true,"ingredients":[{"amount":2,"id":"1","name":"jabuticabas","unit":"cup"},{"amount":3,"id":"2","name":"ovos inteiros","unit":""},{"amount":1,"id":"3","name":"açúcar","unit":"cup"},{"amount":0.5,"id":"4","name":"óleo","unit":"cup"},{"amount":2,"id":"5","name":"farinha de trigo peneirada (ou aveia)","unit":"cup"},{"amount":1,"id":"6","name":"fermento químico em pó","unit":"tbsp"}],"steps":[{"content":"No liquidificador, bata as jabuticabas, os ovos, o açúcar e o óleo por cerca de 1 minuto e meio.","timer":90,"title":"Bater"},{"content":"Numa vasilha, peneire a farinha, junte o creme do liquidificador e misture bem. Adicione o fermento e misture delicadamente.","timer":0,"title":"Misturar"},{"content":"Despeje numa fôrma de pudim untada e enfarinhada e asse a 180 °C por cerca de 40 minutos, até o palito sair limpo.","timer":2400,"title":"Assar"}],"notes":"A receita original não diz temperatura nem tempo: coloquei 180 °C por cerca de 40 minutos, que é o padrão para esse tamanho de bolo. Confira com o palito.","images":[],"source":"Bolo_de_Jabiticaba.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"bolo-de-tapioca","title":"Bolo de tapioca","category":"Bolos","description":"Tapioca granulada hidratada no leite, com coco fresco e manteiga. Úmido e com casquinha dourada.","servings":1,"yieldLabel":"fôrma","scale":true,"ingredients":[{"amount":2,"id":"1","name":"tapioca granulada","unit":"cup"},{"amount":0.5,"id":"2","name":"coco fresco ralado","unit":"cup"},{"amount":150,"id":"3","name":"manteiga em temperatura ambiente (+ para untar)","unit":"g"},{"amount":5,"id":"4","name":"leite","unit":"cup"},{"amount":2,"id":"5","name":"açúcar","unit":"cup"},{"amount":4,"id":"6","name":"ovos grandes","unit":""}],"steps":[{"content":"Num recipiente fundo, misture a tapioca com 3 xícaras do leite e deixe até absorver todo o líquido.","timer":0,"title":"Hidratar a tapioca"},{"content":"Bata o coco com o restante do leite no liquidificador por cerca de 3 minutos.","timer":180,"title":"Bater o coco"},{"content":"Na batedeira, bata a manteiga, os ovos e o açúcar por 10 minutos.","timer":600,"title":"Bater a base"},{"content":"Junte o leite de coco batido e a tapioca hidratada, misturando levemente com uma colher.","timer":0,"title":"Juntar"},{"content":"Despeje numa fôrma com furo no meio untada com manteiga e asse em forno preaquecido a 200 °C por 45 minutos, até começar a dourar.","timer":2700,"title":"Assar"},{"content":"Deixe esfriar um pouco antes de desenformar.","timer":0,"title":"Desenformar"}],"notes":"","images":[],"source":"BOLO_DE_TAPIOCA.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"caldo-de-snapper","title":"Caldo de snapper com dashi (tai-dashi)","category":"Caldos","description":"Caldo claro com a carcaça e a cabeça do snapper, kombu e aromáticos. Vira ushio-jiru só com sal, ou ara-jiru com missô.","servings":4,"scale":true,"ingredients":[{"amount":600,"id":"1","name":"carcaça e cabeça de snapper, sem guelras","unit":"g"},{"amount":1,"id":"2","name":"sal para o shimofuri","unit":"tbsp"},{"amount":1.2,"id":"3","name":"água gelada","unit":"l"},{"amount":1,"id":"4","name":"pedaço de kombu, ~10 cm","unit":""},{"amount":3,"id":"5","name":"shiitake seco","unit":""},{"amount":3,"id":"6","name":"fatias finas de gengibre","unit":""},{"amount":3,"id":"7","name":"talos verdes de cebolinha","unit":""},{"amount":2,"id":"8","name":"saquê ou ryōrishu","unit":"tbsp"},{"amount":1,"id":"9","name":"sal para temperar","unit":"tsp"},{"amount":1,"id":"10","name":"shoyu claro (usukuchi), opcional","unit":"tsp"},{"amount":2,"id":"11","name":"parte branca da cebolinha, picada fina","unit":"tbsp"}],"steps":[{"content":"Retire as guelras de {1} e raspe a linha de sangue ao longo da espinha sob água corrente, com uma colher ou escova limpa.","timer":0,"title":"Limpar"},{"content":"Polvilhe {2} sobre a carcaça e a cabeça para puxar o sangue e o cheiro forte.","timer":1200,"title":"Salgar"},{"content":"Despeje água fervente sobre a carcaça até a superfície ficar esbranquiçada. Passe na hora para água gelada e lave com os dedos, tirando sangue coagulado e escamas.","timer":0,"title":"Shimofuri"},{"content":"Na panela: {3}, {4}, {5}, {6}, {7}, {8} e a carcaça limpa. Deixe de molho com o fogo desligado.","timer":1800,"title":"Molho a frio"},{"content":"Fogo baixo. Quando surgirem bolhinhas no fundo, antes de ferver, retire o kombu.","timer":900,"title":"Aquecer devagar"},{"content":"Fervura bem suave, sem borbulhar forte, tirando a espuma que subir.","timer":1500,"title":"Fervura leve"},{"content":"Coe em pano fino ou coador com papel-toalha, sem espremer.","timer":0,"title":"Coar"},{"content":"Tempere com {9} e, se quiser, {10}. Sirva quente com {11} por cima.","timer":0,"title":"Temperar e servir"}],"notes":"Não deixe o kombu ferver (solta gosma e amarga) nem passe de 40 minutos no fogo (o caldo turva). Para ara-jiru, dissolva missô fora do fogo.","images":[],"updatedAt":"2026-11-01T09:50:00.000Z"},{"id":"carpaccio-de-salmao","title":"Carpaccio de salmão","category":"Peixe cru","description":"Fatias finíssimas de salmão com vinagrete de limão-siciliano, mostarda, alcaparras, dill e pimenta-rosa.","servings":4,"scale":true,"ingredients":[{"amount":300,"id":"1","name":"filé de salmão próprio para sashimi, sem pele","unit":"g"},{"amount":4,"id":"2","name":"azeite extravirgem","unit":"tbsp"},{"amount":2,"id":"3","name":"suco de limão-siciliano","unit":"tbsp"},{"amount":1,"id":"4","name":"raspas de limão-siciliano","unit":"tsp"},{"amount":1,"id":"5","name":"mostarda Dijon","unit":"tsp"},{"amount":0.5,"id":"6","name":"mel","unit":"tsp"},{"amount":1,"id":"7","name":"alcaparras escorridas","unit":"tbsp"},{"amount":1,"id":"8","name":"dill fresco picado","unit":"tbsp"},{"amount":2,"id":"9","name":"cebola roxa bem fina","unit":"tbsp"},{"amount":0.5,"id":"10","name":"flor de sal","unit":"tsp"},{"amount":0.5,"id":"11","name":"pimenta-rosa levemente amassada","unit":"tsp"}],"steps":[{"content":"Embrulhe {1} em filme e deixe no freezer até firmar, sem congelar.","timer":1800,"title":"Firmar o salmão"},{"content":"Com a faca bem afiada, corte fatias finíssimas contra a fibra e arrume num prato frio, sem sobrepor muito. Pode ficar coberto na geladeira por até 2 horas.","timer":0,"title":"Fatiar"},{"content":"Misture {3}, {4}, {5} e {6}. Junte {2} aos poucos, batendo com um garfo até emulsionar.","timer":0,"title":"Fazer o molho"},{"content":"Na hora de servir, regue o molho e espalhe {7}, {9} e {8}. Finalize com {10} e {11}. Sirva em até 5 minutos.","timer":0,"title":"Montar e servir"}],"notes":"O limão começa a \"cozinhar\" o peixe: depois de 10 minutos as bordas ficam opacas. Variações: shoyu e gengibre no lugar de mel e mostarda, ou rúcula e lascas de parmesão.","images":[],"updatedAt":"2026-11-01T09:50:00.000Z"},{"id":"coxinha-de-mandioca","title":"Coxinha de mandioca","category":"Salgados","description":"Massa de mandioca cozida com caldo de frango, mais macia e adocicada que a tradicional. Empanada com água e açúcar, que não deixa doce.","servings":25,"yieldLabel":"coxinhas","scale":true,"ingredients":[{"amount":"","id":"1","name":"## Massa","unit":""},{"amount":1,"id":"2","name":"mandioca cozida","unit":"kg"},{"amount":2,"id":"3","name":"farinha de trigo","unit":"cup"},{"amount":2,"id":"4","name":"manteiga","unit":"tbsp"},{"amount":600,"id":"5","name":"caldo do cozimento do frango (ou 2 tabletes de caldo de galinha em 600 ml de água)","unit":"ml"},{"amount":"","id":"6","name":"cheiro-verde a gosto","unit":""},{"amount":"","id":"7","name":"sal a gosto","unit":""},{"amount":"","id":"8","name":"## Para empanar","unit":""},{"amount":1,"id":"9","name":"água","unit":"l"},{"amount":1,"id":"10","name":"açúcar refinado","unit":"cup"},{"amount":"","id":"11","name":"farinha de rosca","unit":""},{"amount":"","id":"12","name":"óleo para fritar","unit":""},{"amount":"","id":"13","name":"## Recheio","unit":""},{"amount":"","id":"14","name":"frango desfiado, carne moída ou legumes, a gosto","unit":""}],"steps":[{"content":"Amasse a mandioca até virar purê. Junte o caldo, a manteiga, o sal e o cheiro-verde.","timer":0,"title":"Fazer o purê"},{"content":"Leve ao fogo médio. Quando começar a ferver, junte metade da farinha e misture bem. Adicione o resto aos poucos, mexendo sem parar por cerca de 10 minutos.","timer":600,"title":"Cozinhar a massa"},{"content":"Transfira para uma tigela, cubra com filme encostando na massa e deixe esfriar bem. É normal ficar mais mole que a massa tradicional.","timer":0,"title":"Esfriar"},{"content":"Com as mãos untadas com óleo, abra porções de massa, recheie e modele as coxinhas.","timer":0,"title":"Modelar"},{"content":"Dissolva o açúcar na água, passe as coxinhas nessa mistura e depois na farinha de rosca.","timer":0,"title":"Empanar"},{"content":"Frite em óleo quente e escorra numa peneira de metal, não em papel-toalha, para não encharcar.","timer":0,"title":"Fritar"}],"notes":"A água com açúcar ajuda a dourar e deixa a casquinha crocante, sem adoçar. O recheio não vem na receita original.","images":[{"src":"images/coxinha-de-mandioca/01.jpg","caption":"Coxinhas modeladas, antes de empanar."}],"source":"Coxinha_de_Mandioca.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"creme-brulee-catalao","title":"Creme brûlée catalão","category":"Doces","description":"Versão catalã do creme brûlée, cozida na panela com especiarias e raspas de laranja. Precisa de maçarico.","servings":4,"yieldLabel":"tigelinhas","scale":true,"ingredients":[{"amount":250,"id":"1","name":"leite","unit":"ml"},{"amount":250,"id":"2","name":"creme de leite","unit":"ml"},{"amount":2,"id":"3","name":"ramas de canela","unit":""},{"amount":2,"id":"4","name":"estrelas de anis","unit":""},{"amount":2,"id":"5","name":"cravos","unit":""},{"amount":1,"id":"6","name":"fava de baunilha aberta no comprimento","unit":""},{"amount":4,"id":"7","name":"gemas","unit":""},{"amount":120,"id":"8","name":"açúcar","unit":"g"},{"amount":8,"id":"9","name":"farinha de trigo","unit":"g"},{"amount":"","id":"10","name":"raspas finas de casca de laranja","unit":""},{"amount":200,"id":"11","name":"açúcar para caramelizar","unit":"g"}],"steps":[{"content":"Bata as gemas com o açúcar com um batedor de arame até ficar quase branco. Junte a farinha e as raspas de laranja e bata mais um pouco.","timer":0,"title":"Bater as gemas"},{"content":"Ferva o leite e o creme de leite com a canela, o anis, o cravo e a baunilha.","timer":0,"title":"Infusionar"},{"content":"Coe a mistura quente sobre as gemas e bata até ficar homogêneo.","timer":0,"title":"Juntar"},{"content":"Leve a uma panela em fogo baixo por alguns minutos, mexendo sempre para não grudar, até engrossar.","timer":0,"title":"Cozinhar"},{"content":"Distribua nas tigelinhas e leve ao forno a 180 °C por 5 minutos.","timer":300,"title":"Formar a película"},{"content":"Deixe esfriar e leve à geladeira.","timer":0,"title":"Gelar"},{"content":"Cubra com açúcar e caramelize com maçarico. Repita a caramelização para ficar bem crocante.","timer":0,"title":"Caramelizar"}],"notes":"Do chef Claude Troisgros: \"Se você não tem um maçarico de cozinha, não faça creme brûlée.\" O rendimento de 4 tigelinhas é uma estimativa.","images":[],"source":"CREME_BRULE__CATALAO.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"crostoli","title":"Crostoli (grostoli, cueca virada)","category":"Doces","description":"Massa italiana frita, fina e crocante, com o nó característico, passada em açúcar com canela.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":500,"id":"1","name":"farinha de trigo","unit":"g"},{"amount":2,"id":"2","name":"ovos","unit":""},{"amount":1,"id":"3","name":"leite","unit":"cup"},{"amount":4,"id":"4","name":"açúcar","unit":"tbsp"},{"amount":2,"id":"5","name":"grappa ou cachaça","unit":"tbsp"},{"amount":1,"id":"6","name":"banha de porco","unit":"tbsp"},{"amount":1,"id":"7","name":"fermento em pó","unit":"tbsp"},{"amount":3,"id":"8","name":"óleo para fritar","unit":"cup"},{"amount":"","id":"9","name":"## Cobertura","unit":""},{"amount":2,"id":"10","name":"açúcar","unit":"cup"},{"amount":2,"id":"11","name":"canela","unit":"tbsp"}],"steps":[{"content":"Misture a farinha, os ovos, o leite, o açúcar, a cachaça, a banha e o fermento até obter uma massa homogênea e firme.","timer":0,"title":"Fazer a massa"},{"content":"Cubra com filme e deixe na geladeira por 30 minutos.","timer":1800,"title":"Descansar"},{"content":"Retire um pouco de massa por vez, forme bolinhas e abra com rolo na espessura desejada, bem fina. Erga para ver se não gruda.","timer":0,"title":"Abrir"},{"content":"Corte tiras de 3 × 10 cm, faça um pequeno corte no centro e passe uma das pontas por ele, virando para trás.","timer":0,"title":"Cortar e dar o nó"},{"content":"Aqueça o óleo sem exagero, abaixe o fogo e frite aos poucos, virando dos dois lados até dourar.","timer":0,"title":"Fritar"},{"content":"Misture o açúcar e a canela e passe os crostoli fritos ainda quentes.","timer":0,"title":"Cobrir"}],"notes":"Versão salgada: não passe no açúcar com canela. História: nasceu na Roma antiga como frictilia, bolinhos fritos da Saturnália; no Brasil ganhou o nome de cueca virada.","images":[{"src":"images/crostoli/01.jpg","caption":"Crostoli prontos."},{"src":"images/crostoli/02.jpg","caption":"Crostoli com açúcar."},{"src":"images/crostoli/03.jpg","caption":"Misturando a massa."},{"src":"images/crostoli/04.jpg","caption":"Massa homogênea e firme."},{"src":"images/crostoli/05.jpg","caption":"Abrindo com rolo."},{"src":"images/crostoli/06.jpg","caption":"Cortando as tiras."},{"src":"images/crostoli/07.jpg","caption":"Tiras com o nó."},{"src":"images/crostoli/08.jpg","caption":"Fritando."}],"source":"CROSTOLI.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"crustule","title":"Crustule da avó (latugue)","category":"Doces","description":"Receita de família trazida da Itália por volta de 1880: massa finíssima com banha e cachaça de erva-doce, frita e polvilhada com açúcar.","servings":1,"yieldLabel":"receita","scale":false,"ingredients":[{"amount":5,"id":"1","name":"ovos","unit":""},{"amount":1.5,"id":"2","name":"açúcar (+ para polvilhar)","unit":"cup"},{"amount":1,"id":"3","name":"manteiga ou margarina, derretida com a banha","unit":"tbsp"},{"amount":1,"id":"4","name":"banha de porco derretida","unit":"tbsp"},{"amount":1,"id":"5","name":"cachaça aromatizada com erva-doce","unit":"tbsp"},{"amount":900,"id":"6","name":"farinha de trigo, aproximadamente (o quanto baste)","unit":"g"},{"amount":"","id":"7","name":"óleo para fritar","unit":""}],"steps":[{"content":"Bata os ovos, junte o açúcar e continue batendo. Adicione a manteiga derretida com a banha e a cachaça. Um mixer ajuda.","timer":0,"title":"Bater"},{"content":"Vá colocando farinha e amassando até a massa desgrudar bem das mãos.","timer":0,"title":"Sovar"},{"content":"Enrole em filme e deixe na geladeira por algumas horas, de preferência de um dia para o outro.","timer":0,"title":"Descansar"},{"content":"Passe no cilindro até ficar bem fina, cerca de 0,5 mm (posição 5 da Marcato).","timer":0,"title":"Abrir fino"},{"content":"Corte retângulos de cerca de 2 × 5 cm, faça um corte no meio e passe uma das pontas por ele.","timer":0,"title":"Cortar"},{"content":"Frite em óleo quente, mas não muito, até começar a dourar. Polvilhe açúcar assim que tirar do óleo.","timer":0,"title":"Fritar e polvilhar"}],"notes":"Cachaça de erva-doce: coloque sementes de erva-doce num vidro com cachaça e deixe curtir alguns dias.","images":[],"source":"Crustule.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"demi-glace","title":"Demi-glace","category":"Molhos","description":"Molho espanhol com fundo escuro, reduzido à metade até ficar brilhante e encorpado. Base de molhos para carnes.","servings":1,"yieldLabel":"receita (~500 ml)","scale":true,"ingredients":[{"amount":500,"id":"1","name":"molho espanhol","unit":"ml"},{"amount":500,"id":"2","name":"fundo escuro","unit":"ml"},{"amount":2,"id":"3","name":"vinho Madeira ou do Porto (opcional)","unit":"tbsp"}],"steps":[{"content":"Junte {1} e {2} numa panela de fundo grosso e leve à fervura.","timer":0,"title":"Juntar"},{"content":"Cozinhe em fogo baixo, retirando a espuma, até reduzir à metade e cobrir as costas da colher.","timer":2700,"title":"Reduzir"},{"content":"Passe pela peneira fina. Se quiser, junte {3} no final.","timer":0,"title":"Finalizar"}],"notes":"Para molhos de carne: refogue chalota na manteiga, deglaceie com vinho tinto, junte demi-glace e reduza (molho bordelaise), ou junte pimenta verde e creme (molho au poivre). Congela muito bem em forminhas de gelo.","images":[],"source":"","updatedAt":"2026-11-09T03:10:00.000Z"},{"id":"dry-rub-suino","title":"Dry rub suíno","category":"Temperos","description":"Rub em grande quantidade para porco defumado: açúcar demerara, sal rosa, alho, cebola, colorau e um toque de canela e louro.","servings":1,"yieldLabel":"receita (~1 kg)","scale":true,"ingredients":[{"amount":100,"id":"1","name":"alho granulado","unit":"g"},{"amount":50,"id":"2","name":"cebola granulada","unit":"g"},{"amount":250,"id":"3","name":"sal rosa granulado fino","unit":"g"},{"amount":500,"id":"4","name":"açúcar demerara","unit":"g"},{"amount":50,"id":"5","name":"pimenta-do-reino moída grossa","unit":"g"},{"amount":80,"id":"6","name":"colorau ou páprica","unit":"g"},{"amount":10,"id":"7","name":"canela em pó","unit":"g"},{"amount":10,"id":"8","name":"louro em pó","unit":"g"},{"amount":8,"id":"9","name":"pimenta-caiena em pó","unit":"g"}],"steps":[{"content":"Bata a cebola e o alho granulados no liquidificador para diminuir a granulação.","timer":0,"title":"Moer"},{"content":"Numa tigela, junte todos os ingredientes e misture bem.","timer":0,"title":"Misturar"}],"notes":"Bem fechado, dura 6 meses. Sugestão: acrescentar guaraná em pó à mistura.","images":[],"source":"Dry_Rub_Suino.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"empanada-do-douglas","title":"Empanada do Douglas","category":"Salgados","description":"Massa de empanada com banha e um toque de vodka ou cachaça: lisa, fácil de abrir e com casca folhada e crocante, no forno ou na fritura.","servings":1,"yieldLabel":"receita (~2 kg de massa, ~40 discos de 13 cm)","scale":true,"ingredients":[{"id":"1","name":"farinha de trigo (plain flour)","amount":1250,"unit":"g"},{"id":"2","name":"água quente (~60 °C)","amount":575,"unit":"g"},{"id":"3","name":"vodka ou cachaça","amount":50,"unit":"g"},{"id":"4","name":"banha ou gordura animal derretida (morna)","amount":150,"unit":"g"},{"id":"5","name":"sal","amount":25,"unit":"g"}],"steps":[{"title":"Preparar o líquido","content":"Dissolva {5} na {2} e junte {3}. A água deve estar quente, mas ainda suportável ao toque."},{"title":"Incorporar a água","content":"Coloque {1} numa tigela grande (ou na batedeira com gancho) e adicione o líquido aos poucos, misturando até não sobrar farinha seca."},{"title":"Sovar","content":"Misture e sove por 5 minutos, até a massa ficar homogênea.","timer":300},{"title":"Juntar a gordura","content":"Adicione {4} no final, aos poucos, e sove até ela ser toda absorvida e a massa voltar a ficar lisa e macia (3 a 5 minutos). No começo a massa escorrega e parece que não vai incorporar: continue."},{"title":"Descansar","content":"Embrulhe a massa em filme plástico e deixe descansar 30 minutos em temperatura ambiente. O glúten relaxa e a massa abre sem encolher.","timer":1800},{"title":"Abrir e cortar","content":"Divida a massa em 4 partes. Abra cada uma com rolo até 2 a 3 mm de espessura e corte discos de 13 cm. Mantenha o que não estiver usando coberto, para não ressecar."},{"title":"Rechear e fechar","content":"Coloque o recheio frio no centro de cada disco, dobre ao meio, aperte as bordas e faça o repulgue (a dobrinha trançada) ou feche com um garfo."},{"title":"Assar ou fritar","content":"No forno: pincele com ovo batido e asse a 200 °C por 15 a 20 minutos, até dourar. Na fritura: frite em óleo a 170–175 °C até dourar dos dois lados e escorra em papel.","timer":1080}],"notes":"Podem ser assadas ou fritas: assadas (200 °C, pinceladas com ovo) ficam mais leves e douradas por igual; fritas (170–175 °C) ficam mais crocantes e com a casca cheia de bolhinhas. A mesma massa serve para as duas.\n\nO que foi interpretado ou completado:\n- A anotação original dizia \"1250kg farinha\" e \"575 kg água\": li como gramas (1250 g e 575 g). Isso dá 46% de água em relação à farinha, a proporção típica de massa de empanada.\n- \"25g salt\" = 25 g de sal (2% da farinha).\n- Dissolver o sal na água junto com a vodka, a temperatura da água (~60 °C), o descanso de 30 minutos, a espessura, o tamanho dos discos e os tempos de forno e fritura foram completados por mim; não estavam na receita.\n- O tempo para incorporar a gordura (3 a 5 minutos) também é estimativa.\n- O rendimento (~40 discos) é aproximado: 2 kg de massa em discos de 13 cm com 2 a 3 mm. Para empanadas de festa, corte discos de 9 a 10 cm.\n\nPor que vodka ou cachaça: o álcool atrapalha a formação de glúten e evapora no calor, então a massa fica mais macia de abrir e com casca folhada e crocante, cheia de bolhinhas na fritura. Não fica gosto de bebida.\n\nA gordura vai derretida, mas morna: quente demais, ela começa a cozinhar a farinha.\n\nNa Austrália: banha é \"lard\" (tem nos supermercados, perto da manteiga) e também serve \"beef dripping\". Farinha de trigo comum é \"plain flour\". Trocar a banha por manteiga ou gordura vegetal funciona, mas a massa fica menos folhada.\n\nA massa crua não deve ser provada (farinha crua não é segura). A massa aguenta até 2 dias na geladeira bem embrulhada; tire 20 minutos antes de abrir.","images":[{"src":"images/empanada-do-douglas/01.jpg","caption":"Fritas: casca cheia de bolhinhas e repulgue."},{"src":"images/empanada-do-douglas/02.jpg","caption":"Assadas, pinceladas com ovo."}],"source":"Receita do Douglas","updatedAt":"2026-11-10T04:10:00.000Z"},{"id":"fumet-de-peixe","title":"Fumet de peixe","category":"Fundos","description":"Fundo rápido de espinhas de peixe branco com vinho branco, pronto em 30 minutos. Use a carcaça do snapper.","servings":1,"yieldLabel":"receita (~1 l)","scale":true,"ingredients":[{"amount":1,"id":"1","name":"espinhas e cabeças de peixe branco (snapper, linguado), sem guelras e sem sangue","unit":"kg"},{"amount":30,"id":"2","name":"manteiga","unit":"g"},{"amount":"","id":"3","name":"## Mirepoix branco","unit":""},{"amount":100,"id":"4","name":"cebola em fatias finas","unit":"g"},{"amount":50,"id":"5","name":"aipo (salsão)","unit":"g"},{"amount":50,"id":"6","name":"alho-poró, parte branca","unit":"g"},{"amount":50,"id":"7","name":"talos de cogumelo (opcional)","unit":"g"},{"amount":"","id":"8","name":"## Líquido","unit":""},{"amount":150,"id":"9","name":"vinho branco seco","unit":"ml"},{"amount":1.2,"id":"10","name":"água fria","unit":"l"},{"amount":"","id":"11","name":"## Ervas","unit":""},{"amount":1,"id":"12","name":"folha de louro","unit":""},{"amount":1,"id":"13","name":"ramo de tomilho","unit":""},{"amount":5,"id":"14","name":"talos de salsinha","unit":""},{"amount":5,"id":"15","name":"grãos de pimenta-branca","unit":""}],"steps":[{"content":"Tire as guelras e lave bem as espinhas em água fria até sair todo o sangue. Corte em pedaços.","timer":0,"title":"Limpar as espinhas"},{"content":"Derreta {2} e sue os legumes com as espinhas em fogo baixo, tampado, sem dourar.","timer":300,"title":"Suar"},{"content":"Junte {9} e deixe reduzir pela metade.","timer":0,"title":"Deglacear"},{"content":"Cubra com {10}, junte as ervas, leve à fervura, retire a espuma e mantenha em fervura bem leve.","timer":1500,"title":"Cozinhar"},{"content":"Coe sem espremer e esfrie rápido.","timer":0,"title":"Coar"}],"notes":"Não passe de 30 minutos: espinha de peixe cozida demais deixa o fumet amargo e turvo. Use só peixe branco e magro (salmão e peixes gordos deixam o fundo forte). Sem sal. Ótimo para risoto de frutos do mar, molho beurre blanc e velouté de peixe.","images":[{"src":"images/fumet-de-peixe/01.jpg","caption":"Ilustração"}],"source":"","updatedAt":"2026-11-09T03:10:00.000Z"},{"id":"fundo-claro-de-ave","title":"Fundo claro de ave (fond blanc)","category":"Fundos","description":"Fundo clássico de carcaça de frango sem tostar, com mirepoix branco. Base de velouté, risotos, sopas e molhos claros.","servings":1,"yieldLabel":"receita (~1,5 l)","scale":true,"ingredients":[{"amount":1,"id":"1","name":"carcaças, pescoços e asas de frango","unit":"kg"},{"amount":2.5,"id":"2","name":"água fria","unit":"l"},{"amount":"","id":"3","name":"## Mirepoix branco","unit":""},{"amount":125,"id":"4","name":"cebola","unit":"g"},{"amount":60,"id":"5","name":"aipo (salsão)","unit":"g"},{"amount":60,"id":"6","name":"alho-poró, parte branca","unit":"g"},{"amount":"","id":"7","name":"## Bouquet garni (ervas aromáticas)","unit":""},{"amount":2,"id":"8","name":"ramos de tomilho","unit":""},{"amount":1,"id":"9","name":"folha de louro","unit":""},{"amount":5,"id":"10","name":"talos de salsinha","unit":""},{"amount":6,"id":"11","name":"grãos de pimenta-do-reino","unit":""}],"steps":[{"content":"Tire o excesso de gordura e restos de sangue e lave os ossos em água fria.","timer":0,"title":"Limpar os ossos"},{"content":"Para um fundo mais límpido, cubra os ossos com água fria, deixe ferver, descarte a água e enxágue os ossos.","timer":0,"title":"Branquear (opcional)"},{"content":"Coloque os ossos com {2} na panela e leve ao fogo médio até começar a ferver. Retire toda a espuma.","timer":0,"title":"Começar a frio"},{"content":"Abaixe para uma fervura bem suave, sem tampa, retirando espuma e gordura de tempos em tempos.","timer":5400,"title":"Fervura leve"},{"content":"Junte o mirepoix e o bouquet garni e continue em fervura leve.","timer":3600,"title":"Aromáticos"},{"content":"Coe num pano ou peneira fina, sem espremer. Esfrie rápido e, depois de gelado, retire a gordura que endurecer por cima.","timer":0,"title":"Coar e esfriar"}],"notes":"Tempo total: 2h30 a 3h. Não deixe ferver forte: o fundo fica turvo. Sem sal. Para fundo claro de vitela, use ossos de vitela e cozinhe 5–6 horas. Dura 3–4 dias na geladeira e 3 meses no congelador.","images":[{"src":"images/fundo-claro-de-ave/01.jpg","caption":"Ilustração"}],"source":"","updatedAt":"2026-11-09T03:10:00.000Z"},{"id":"fundo-claro-de-legumes","title":"Fundo claro de legumes","category":"Fundos","description":"Fundo básico de legumes e ervas aromáticas, sem ossos. Base para risotos, sopas, velouté de legumes e cozimentos delicados.","servings":1,"yieldLabel":"receita (~1,5 l)","scale":true,"ingredients":[{"amount":"","id":"1","name":"## Mirepoix (~460 g, metade cebola)","unit":""},{"amount":250,"id":"2","name":"cebola em pedaços médios","unit":"g"},{"amount":70,"id":"3","name":"aipo (salsão)","unit":"g"},{"amount":70,"id":"4","name":"alho-poró, parte branca","unit":"g"},{"amount":70,"id":"5","name":"cenoura","unit":"g"},{"amount":"","id":"6","name":"## Líquido","unit":""},{"amount":2,"id":"7","name":"água fria","unit":"l"},{"amount":"","id":"8","name":"## Bouquet garni (ervas aromáticas)","unit":""},{"amount":2,"id":"9","name":"ramos de tomilho","unit":""},{"amount":1,"id":"10","name":"folha de louro","unit":""},{"amount":5,"id":"11","name":"talos de salsinha","unit":""},{"amount":6,"id":"12","name":"grãos de pimenta-do-reino","unit":""}],"steps":[{"content":"Corte os legumes em pedaços médios, de 2–3 cm. Lave bem o alho-poró, que costuma ter terra entre as camadas.","timer":0,"title":"Cortar"},{"content":"Amarre o tomilho, o louro e os talos de salsinha com barbante (ou num saquinho de pano, junto com a pimenta).","timer":0,"title":"Montar o bouquet"},{"content":"Coloque os legumes e o bouquet na panela com {7} e leve ao fogo médio até começar a ferver.","timer":0,"title":"Começar a frio"},{"content":"Abaixe para fervura bem suave, sem tampa, retirando a espuma que subir.","timer":2700,"title":"Cozinhar em fervura leve"},{"content":"Coe sem espremer os legumes. Esfrie rápido (panela sobre água com gelo) e guarde.","timer":0,"title":"Coar"}],"notes":"Fundo não leva sal: ele será reduzido depois. Mais de 1 hora de cozimento deixa o fundo de legumes amargo. Para mais sabor, sue os legumes em um fio de óleo por 5 minutos, sem dourar, antes da água. Dura 3–4 dias na geladeira e 3 meses no congelador (em forminhas de gelo é prático).","images":[{"src":"images/fundo-claro-de-legumes/01.jpg","caption":"Ilustração"}],"source":"","updatedAt":"2026-11-09T03:10:00.000Z"},{"id":"fundo-escuro","title":"Fundo escuro","category":"Fundos","description":"Fundo de ossos e mirepoix tostados, com extrato de tomate e vinho tinto. Base do molho espanhol e do demi-glace.","servings":1,"yieldLabel":"receita (~1 l)","scale":true,"ingredients":[{"amount":600,"id":"1","name":"recortes de ossos (boi ou vitela; joelho e tutano são ótimos)","unit":"g"},{"amount":"","id":"2","name":"## Mirepoix (500 g)","unit":""},{"amount":250,"id":"3","name":"cebola","unit":"g"},{"amount":125,"id":"4","name":"cenoura","unit":"g"},{"amount":125,"id":"5","name":"aipo (salsão)","unit":"g"},{"amount":"","id":"6","name":"## Para tostar e deglacear","unit":""},{"amount":50,"id":"7","name":"extrato de tomate","unit":"g"},{"amount":100,"id":"8","name":"vinho tinto seco","unit":"ml"},{"amount":2.5,"id":"9","name":"água fria","unit":"l"},{"amount":"","id":"10","name":"## Ervas","unit":""},{"amount":2,"id":"11","name":"ramos de tomilho","unit":""},{"amount":1,"id":"12","name":"ramo de alecrim","unit":""},{"amount":2,"id":"13","name":"folhas de louro","unit":""},{"amount":8,"id":"14","name":"grãos de pimenta-do-reino","unit":""}],"steps":[{"content":"Espalhe os ossos numa assadeira e asse a 220 °C, virando na metade, até ficarem bem dourados, cor de caramelo escuro, sem queimar.","timer":2700,"title":"Tostar os ossos"},{"content":"Junte o mirepoix em pedaços grandes à assadeira e asse até caramelizar.","timer":1200,"title":"Tostar o mirepoix"},{"content":"Espalhe {7} sobre ossos e legumes e volte ao forno até ficar cor de tijolo. Isso tira a acidez do tomate.","timer":420,"title":"Pinçage"},{"content":"Passe tudo para a panela. Leve a assadeira ao fogo com {8} e raspe o fundo com espátula para soltar o caramelizado. Despeje na panela.","timer":0,"title":"Deglacear"},{"content":"Cubra com {9}, leve à fervura e retire a espuma. Junte as ervas.","timer":0,"title":"Cobrir com água fria"},{"content":"Cozinhe em fervura bem suave, sem tampa, de 4 a 6 horas (até 8 para ossos de boi), retirando espuma e gordura. Complete com água fria se baixar além dos ossos.","timer":18000,"title":"Fervura leve"},{"content":"Coe numa peneira fina. Esfrie rápido e retire a gordura endurecida por cima.","timer":0,"title":"Coar e desengordurar"}],"notes":"Sem sal. Se queimar os ossos, o fundo fica amargo: dourado escuro é o ponto. Ao reduzir até virar uma calda grossa e brilhante (cerca de 1/10 do volume), vira glace de viande, ótima para finalizar molhos. Dura 4–5 dias na geladeira e 3 meses no congelador.","images":[{"src":"images/fundo-escuro/01.jpg","caption":"Ilustração"}],"source":"","updatedAt":"2026-11-09T03:10:00.000Z"},{"id":"gunkan-de-salmao","title":"Gunkan de salmão","category":"Sushi","description":"O \"barquinho\" tradicional: bolinho de arroz cercado por uma faixa de nori, com salmão picado por cima. Aproveita as aparas do sashimi e do nigiri. Rende 6 peças por folha de nori.","servings":6,"yieldLabel":"peças","scale":true,"ingredients":[{"amount":90,"id":"1","name":"arroz de sushi pronto (shari)","unit":"g"},{"amount":1,"id":"2","name":"folha de nori","unit":""},{"amount":80,"id":"3","name":"aparas de salmão sem pele (cauda, bordas)","unit":"g"},{"amount":1,"id":"4","name":"cebolinha bem fina","unit":"tbsp"},{"amount":1,"id":"5","name":"shoyu","unit":"tsp"},{"amount":1,"id":"6","name":"maionese japonesa (opcional)","unit":"tsp"}],"steps":[{"content":"Corte {2} com tesoura em 6 tiras de 3,5 × 19 cm, no sentido das linhas da folha.","timer":0,"title":"Cortar o nori"},{"content":"Pique {3} na faca em cubinhos de 3–5 mm. Misture com {4}, {5} e, se quiser, {6}. Mantenha na geladeira até montar.","timer":0,"title":"Preparar o recheio"},{"content":"Com as mãos úmidas, divida {1} em bolinhos ovais de ~15 g (cerca de 4 × 2,5 cm e 2 cm de altura), sem apertar.","timer":0,"title":"Formar os bolinhos"},{"content":"Envolva cada bolinho com uma tira de nori, lado brilhante para fora e base alinhada com o arroz, deixando ~1,5 cm de \"parede\" acima. Cole a ponta com um grão de arroz amassado.","timer":0,"title":"Enrolar o nori"},{"content":"Coloque 12–15 g de recheio por peça, formando um montinho ~1 cm acima da borda. Sirva na hora: o nori amolece em poucos minutos.","timer":0,"title":"Rechear e servir"}],"notes":"Clássico japonês: ikura (ova de salmão) no lugar do picado, ~15 g por peça. Monte só na hora de servir.","images":[{"src":"images/gunkan-de-salmao/01.jpg","caption":"Gunkans com recheios picados."},{"src":"images/gunkan-de-salmao/02.png","caption":"Esquema: de onde tirar o salmão, como cortar o nori e como montar."}],"updatedAt":"2026-11-02T09:15:00.000Z"},{"id":"jo-de-salmao","title":"Jô de salmão","category":"Sushi","description":"Versão brasileira do gunkan: uma fatia longa de salmão faz o papel do nori, cercando o arroz, com recheio cremoso por cima.","servings":6,"yieldLabel":"peças","scale":true,"ingredients":[{"amount":90,"id":"1","name":"arroz de sushi pronto (shari)","unit":"g"},{"amount":90,"id":"2","name":"lombo de salmão para as fatias","unit":"g"},{"amount":50,"id":"3","name":"aparas de salmão picadas","unit":"g"},{"amount":30,"id":"4","name":"cream cheese","unit":"g"},{"amount":1,"id":"5","name":"cebolinha bem fina","unit":"tbsp"},{"amount":6,"id":"6","name":"fatias finas de jalapeño ou cebolinha para finalizar","unit":""}],"steps":[{"content":"Embrulhe {2} em filme e deixe no freezer até firmar, sem congelar.","timer":1200,"title":"Firmar o lombo"},{"content":"Com a faca deitada, paralela à tábua, corte camadas de 2–3 mm ao longo do bloco, num puxão longo por camada. Corte em tiras de ~12–14 × 3 cm (~15 g cada), com as listras de gordura atravessadas.","timer":0,"title":"Fatiar no comprimento"},{"content":"Misture {3}, {4} e {5}. Mantenha na geladeira.","timer":0,"title":"Fazer o recheio"},{"content":"Com as mãos úmidas, divida {1} em bolinhos redondos de ~15 g, com ~3,5 cm de diâmetro, 2 cm de altura e topo reto.","timer":0,"title":"Formar os bolinhos"},{"content":"Enrole uma tira de salmão em volta de cada bolinho, base alinhada e ~1 cm acima do arroz. Sobreponha as pontas ~1 cm e pressione: o salmão gruda sozinho. Se a tira for curta, emende duas.","timer":0,"title":"Envolver com salmão"},{"content":"Coloque 10–15 g de recheio por peça e finalize com {6}. Sirva logo ou mantenha na geladeira até servir.","timer":0,"title":"Rechear e finalizar"}],"notes":"Recheio picante: salmão picado + maionese japonesa + sriracha, com fatia de jalapeño. Opcional: maçaricar de leve o topo (aburi) ou finalizar com ikura ou tobiko.","images":[{"src":"images/jo-de-salmao/01.jpg","caption":"Jô de salmão com recheio cremoso e jalapeño."},{"src":"images/jo-de-salmao/02.png","caption":"Esquema: de onde tirar a fatia, como fatiar no comprimento e como montar."}],"updatedAt":"2026-11-02T09:15:01.000Z"},{"id":"leitoa-recheada","title":"Leitoa recheada com arroz","category":"Churrasco","description":"Leitoa de 4–5 kg marinada por dentro na seringa, recheada com arroz de carne moída, frutas secas e castanhas, assada no rolete ou no forno.","servings":1,"yieldLabel":"leitoa (4–5 kg)","scale":false,"ingredients":[{"amount":"","id":"1","name":"## Recheio","unit":""},{"amount":3,"id":"2","name":"arroz parboilizado","unit":"cup"},{"amount":150,"id":"3","name":"manteiga","unit":"g"},{"amount":"","id":"4","name":"óleo para fritar a carne moída","unit":""},{"amount":500,"id":"5","name":"carne moída","unit":"g"},{"amount":2,"id":"6","name":"cubos de caldo de galinha","unit":""},{"amount":1,"id":"7","name":"cebola grande picada","unit":""},{"amount":0.75,"id":"8","name":"passas sem sementes","unit":"cup"},{"amount":0.75,"id":"9","name":"nozes picadas","unit":"cup"},{"amount":0.75,"id":"10","name":"amêndoas laminadas","unit":"cup"},{"amount":0.75,"id":"11","name":"castanha de caju picada","unit":"cup"},{"amount":1,"id":"12","name":"azeitonas pretas","unit":"cup"},{"amount":8,"id":"13","name":"dentes de alho fatiados","unit":""},{"amount":2,"id":"14","name":"cheiro-verde (salsinha, cebolinha, orégano fresco, sálvia e manjericão)","unit":"cup"},{"amount":1,"id":"15","name":"copo de vinho branco seco","unit":""},{"amount":"","id":"16","name":"sal temperado ou sal + pimenta-do-reino, pimenta vermelha, noz-moscada, cominho a gosto","unit":""},{"amount":"","id":"17","name":"## Leitoa e marinada","unit":""},{"amount":1,"id":"18","name":"leitoa de cerca de 4,5 kg","unit":""},{"amount":"","id":"19","name":"¾ de copo (250 ml) de vinagre branco","unit":""},{"amount":"","id":"20","name":"¼ de copo (250 ml) de molho inglês","unit":""},{"amount":2,"id":"21","name":"sal (bem cheias)","unit":"tbsp"},{"amount":"","id":"22","name":"sal temperado para esfregar na pele","unit":""}],"steps":[{"content":"Misture o vinagre, o molho inglês e o sal. Com uma seringa culinária, injete a marinada sempre pelo lado de dentro, sem furar a pele (isso prejudica a pururuca).","timer":0,"title":"Marinar a leitoa"},{"content":"Esfregue sal temperado em toda a pele, mantendo-a seca. Deixe no tempero por pelo menos 12 horas na geladeira.","timer":0,"title":"Temperar a pele"},{"content":"Frite a carne moída no óleo. Junte o alho, depois a cebola, até murchar. Adicione o vinho e deixe evaporar.","timer":0,"title":"Refogar a carne do recheio"},{"content":"Junte o caldo de galinha, passas, nozes, amêndoas, castanha, azeitonas e o sal temperado. Mexa por 2 minutos e cubra com água fervendo até um dedo acima.","timer":120,"title":"Temperar o recheio"},{"content":"Em outra panela, refogue o arroz como de costume, adicione água e cozinhe até quase secar.","timer":0,"title":"Cozinhar o arroz"},{"content":"Junte o refogado de carne ao arroz e cozinhe até secar toda a água. Acrescente o cheiro-verde e misture.","timer":0,"title":"Juntar e finalizar o recheio"},{"content":"Escorra o líquido que se formou dentro da leitoa, recheie com o arroz e costure a abertura com barbante.","timer":0,"title":"Rechear"},{"content":"Asse em fogo moderado por cerca de 3 horas e depois em fogo mais alto por mais 1 hora, para a pele pururucar. No rolete, o tempo é semelhante.","timer":10800,"title":"Assar"}],"notes":"Ponto da pele: ela precisa ficar seca o tempo todo para pururucar. Se assar no forno, use temperatura moderada (180 °C) e termine a 220–230 °C.","images":[{"src":"images/leitoa-recheada/01.jpg","caption":"Leitoa assada e recheada."},{"src":"images/leitoa-recheada/02.jpg","caption":"Refogado de carne coberto com água."},{"src":"images/leitoa-recheada/03.jpg","caption":"Arroz quase seco."},{"src":"images/leitoa-recheada/04.jpg","caption":"Juntando o refogado ao arroz."},{"src":"images/leitoa-recheada/05.jpg","caption":"Recheio pronto."},{"src":"images/leitoa-recheada/06.jpg","caption":"Recheando a leitoa."},{"src":"images/leitoa-recheada/07.jpg","caption":"Costurando com barbante."}],"source":"Leitoa_Recheada_Rolete.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"linguica-calabresa-caseira","title":"Linguiça calabresa caseira","category":"Embutidos","description":"Paleta de porco com toucinho, erva-doce tostada, páprica e pimenta calabresa.","servings":9,"yieldLabel":"linguiças","scale":true,"ingredients":[{"amount":1,"id":"1","name":"paleta de porco em cubos","unit":"kg"},{"amount":200,"id":"2","name":"toucinho em cubos","unit":"g"},{"amount":3,"id":"3","name":"sementes de erva-doce","unit":"tbsp"},{"amount":4,"id":"4","name":"dentes de alho picados","unit":""},{"amount":1.5,"id":"5","name":"páprica","unit":"tbsp"},{"amount":1,"id":"6","name":"sal","unit":"tbsp"},{"amount":4,"id":"7","name":"pimenta calabresa","unit":"tsp"},{"amount":1,"id":"8","name":"pimenta-do-reino","unit":"tsp"},{"amount":2,"id":"9","name":"vinho branco seco","unit":"tbsp"},{"amount":1,"id":"10","name":"tripa","unit":""}],"steps":[{"content":"Deixe a paleta, o toucinho e o moedor no congelador por 30 minutos.","timer":1800,"title":"Gelar"},{"content":"Toste a erva-doce em frigideira em fogo alto até ficar perfumada e começar a soltar fumaça. Macere no pilão e misture com o alho, o sal, as pimentas e a páprica.","timer":0,"title":"Tostar a erva-doce"},{"content":"Moa a carne parcialmente congelada no disco médio. Junte os temperos e o vinho e misture com as mãos por 2–3 minutos.","timer":150,"title":"Moer e temperar"},{"content":"Cubra com filme e leve à geladeira por pelo menos 1 hora, ou de um dia para o outro.","timer":3600,"title":"Descansar"},{"content":"Deixe a tripa de molho em água fria por 30 minutos e enxágue por dentro e por fora.","timer":1800,"title":"Preparar a tripa"},{"content":"Acople o funil ao moedor, coloque toda a tripa nele e comece a moer. Quando a carne chegar na ponta, dê um nó. Continue enchendo e dê um nó na outra ponta.","timer":0,"title":"Embutir"},{"content":"Torça a linguiça em direções opostas no tamanho desejado e faça 2–3 furinhos em cada gomo.","timer":0,"title":"Fazer os gomos"},{"content":"Cozinhe como quiser, ou guarde até 3 dias na geladeira ou 3 meses no congelador.","timer":0,"title":"Guardar"}],"notes":"Dicas gerais: gordura de 20 a 30% para a linguiça ficar suculenta. Trabalhe tudo o mais frio possível: carne quase congelada, tigela sobre gelo, utensílios gelados. Corte em cubos de até 2 cm e marine com os temperos pelo menos 30 minutos antes de moer. Sal médio: 10 g para cada 500 g de carne. Depois de moer, misture até a massa ficar pegajosa e homogênea; líquidos (vinho, água) entram nessa hora, bem gelados. Deixe a tripa de molho pelo menos 30 minutos e enxágue por dentro e por fora.","images":[],"source":"Linguica_Caseira.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"linguica-pernil-queijo","title":"Linguiça de pernil com queijo","category":"Embutidos","description":"Pernil em cubos de 1 cm com muçarela (ou provolone), cura opcional de um a dois dias na geladeira.","servings":1,"yieldLabel":"kg de carne","scale":true,"ingredients":[{"amount":1,"id":"1","name":"pernil suíno, sem pele e sem nervos","unit":"kg"},{"amount":300,"id":"2","name":"queijo muçarela, prato, coalho ou provolone","unit":"g"},{"amount":2,"id":"3","name":"leite em pó","unit":"tbsp"},{"amount":"","id":"4","name":"salsinha e cebolinha a gosto","unit":""},{"amount":12,"id":"5","name":"sal","unit":"g"},{"amount":4,"id":"6","name":"dentes de alho amassados","unit":""},{"amount":1,"id":"7","name":"açúcar (colher de sobremesa)","unit":"tsp"},{"amount":50,"id":"8","name":"água gelada","unit":"ml"},{"amount":1,"id":"9","name":"glutamato monossódico (opcional)","unit":"tsp"},{"amount":2.4,"id":"10","name":"sal de cura (opcional)","unit":"g"},{"amount":2,"id":"11","name":"aroma natural de fumaça (opcional)","unit":"tbsp"},{"amount":"","id":"12","name":"6 m de tripa ovina fina ou 3 m de tripa suína 32/34","unit":""}],"steps":[{"content":"Limpe o pernil, tire a pele e o máximo de tecido conjuntivo. Corte em cubos de cerca de 1 cm.","timer":0,"title":"Limpar e cortar"},{"content":"Junte todos os ingredientes, menos o queijo, e misture com as mãos ou na batedeira com a pá, em velocidade baixa, até a carne ficar pegajosa.","timer":0,"title":"Dar liga"},{"content":"Deixe na geladeira por 1 a 2 dias para o tempero se incorporar (e o sal de cura agir, se usado).","timer":0,"title":"Curar"},{"content":"Corte o queijo em cubos de 1 cm e misture uniformemente.","timer":0,"title":"Juntar o queijo"},{"content":"Encha a tripa com funil ou embutidora própria. Moedor caseiro não é recomendado aqui.","timer":0,"title":"Embutir"}],"notes":"Não precisa deixar a gordura do pernil: o queijo faz esse papel. A tripa ovina é mais macia e assa mais rápido, mas rompe com mais facilidade e é mais cara; na dúvida, use a suína.","images":[],"source":"Linguica_Caseira.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"linguica-de-porco-caseira","title":"Linguiça de porco caseira","category":"Embutidos","description":"A mais simples: pernil e toucinho moídos grosso com alho, sal e pimenta, amarrada a cada 10 cm.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":1,"id":"1","name":"pernil de porco","unit":"kg"},{"amount":400,"id":"2","name":"toucinho sem couro","unit":"g"},{"amount":5,"id":"3","name":"dentes de alho","unit":""},{"amount":0.5,"id":"4","name":"pimenta-do-reino (colher de café)","unit":"tsp"},{"amount":1.5,"id":"5","name":"sal","unit":"tbsp"},{"amount":1,"id":"6","name":"vinagre (para a tripa)","unit":"tbsp"},{"amount":"","id":"7","name":"tripa de porco salgada","unit":""},{"amount":"","id":"8","name":"barbante","unit":""}],"steps":[{"content":"No moedor com o disco mais grosso, moa o pernil, o toucinho e o alho uma única vez: pedaços maiores dão mais sabor.","timer":0,"title":"Moer"},{"content":"Junte a pimenta e o sal e misture muito bem.","timer":0,"title":"Temperar"},{"content":"Deixe 3 horas na geladeira.","timer":10800,"title":"Descansar"},{"content":"Perto de embutir, deixe a tripa em água com vinagre por 30 minutos e lave bem em água corrente.","timer":1800,"title":"Preparar a tripa"},{"content":"Encha a tripa com o funil e amarre com barbante a cada 10 cm. Conserve na geladeira.","timer":0,"title":"Embutir e amarrar"}],"notes":"Variações de sabor: hortelã (1 maço, ou desidratada, para 4 kg de carne), erva-doce, provolone, azeitona, rúcula com tomate seco, chimichurri, páprica, noz-moscada.","images":[],"source":"Linguica_Caseira.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"marinada-jacks-old-south","title":"Marinada Jack's Old South","category":"Temperos","description":"Marinada de competição de Myron Mixon (Jack's Old South): suco de maçã, molho inglês, laranja e açúcar mascavo.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":1.9,"id":"1","name":"suco de maçã (2 quarts americanos)","unit":"l"},{"amount":1,"id":"2","name":"molho inglês","unit":"cup"},{"amount":1,"id":"3","name":"suco de laranja","unit":"cup"},{"amount":1,"id":"4","name":"açúcar mascavo claro","unit":"cup"},{"amount":0.5,"id":"5","name":"azeite","unit":"cup"},{"amount":0.5,"id":"6","name":"suco de limão","unit":"cup"},{"amount":2,"id":"7","name":"molho de pimenta","unit":"tbsp"},{"amount":0.5,"id":"8","name":"vinagre de maçã","unit":"cup"},{"amount":0.5,"id":"9","name":"sal","unit":"cup"}],"steps":[{"content":"Aqueça todos os ingredientes, batendo até o açúcar e o sal dissolverem.","timer":0,"title":"Dissolver"},{"content":"Deixe esfriar completamente antes de colocar a carne.","timer":0,"title":"Esfriar"}],"notes":"A receita original usa \"2 quarts\" de suco de maçã, medida americana: são cerca de 1,9 litro. As xícaras são as americanas (240 ml).","images":[],"source":"BBB_Temperos_Miron_Mixon.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-barbecue-outback","title":"Molho barbecue (estilo Outback)","category":"Molhos","description":"Barbecue frio de ketchup, vinagre de maçã e molho inglês, com cravo, canela e caiena.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":0.667,"id":"1","name":"ketchup","unit":"cup"},{"amount":2,"id":"2","name":"vinagre de maçã","unit":"tbsp"},{"amount":1.5,"id":"3","name":"molho inglês","unit":"tbsp"},{"amount":0.5,"id":"4","name":"água (pouco menos)","unit":"cup"},{"amount":"","id":"5","name":"sal, cravo em pó, canela em pó e pimenta-caiena a gosto","unit":""}],"steps":[{"content":"Misture tudo muito bem e use na receita que preferir.","timer":0,"title":"Misturar"}],"notes":"No original, a linha da água está confusa (\"1 e 1/2 colher (sopa) de pouco menos de 1/2 xícara de água\"): usei pouco menos de ½ xícara. Ajuste a gosto.","images":[],"source":"Molhos.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-barbecue-classico","title":"Molho barbecue com suco de maçã","category":"Molhos","description":"Barbecue caseiro de panela, com ketchup, suco de maçã, mel e páprica defumada, batido no final.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":4,"id":"1","name":"óleo de girassol ou canola","unit":"tbsp"},{"amount":1,"id":"2","name":"cebola pequena bem picada","unit":""},{"amount":2,"id":"3","name":"dentes de alho amassados","unit":""},{"amount":4,"id":"4","name":"suco de maçã","unit":"tbsp"},{"amount":3,"id":"5","name":"ketchup","unit":"tbsp"},{"amount":2,"id":"6","name":"vinagre de maçã","unit":"tbsp"},{"amount":1,"id":"7","name":"açúcar mascavo (bem cheia)","unit":"tbsp"},{"amount":1,"id":"8","name":"mel","unit":"tbsp"},{"amount":4,"id":"9","name":"água","unit":"tbsp"},{"amount":2,"id":"10","name":"molho de pimenta","unit":"tsp"},{"amount":1,"id":"11","name":"molho inglês","unit":"tsp"},{"amount":1,"id":"12","name":"mostarda (bem cheia)","unit":"tsp"},{"amount":1,"id":"13","name":"páprica defumada ou pimenta ancho em pó","unit":"tsp"},{"amount":0.25,"id":"14","name":"sal de aipo","unit":"tsp"},{"amount":0.25,"id":"15","name":"pimenta-da-jamaica","unit":"tsp"},{"amount":"","id":"16","name":"sal e pimenta-do-reino moída na hora","unit":""}],"steps":[{"content":"Aqueça o óleo numa panela pequena de fundo grosso e frite a cebola em fogo médio por cerca de 5 minutos, até ficar macia sem dourar.","timer":300,"title":"Refogar"},{"content":"Junte o alho e frite por mais 2 minutos.","timer":120,"title":"Alho"},{"content":"Junte todos os outros ingredientes, misture e leve à fervura.","timer":0,"title":"Ferver"},{"content":"Abaixe para fervura leve e cozinhe destampado por 15 minutos, até engrossar.","timer":900,"title":"Reduzir"},{"content":"Bata no liquidificador ou com mixer até ficar liso.","timer":0,"title":"Bater"}],"notes":"","images":[],"source":"CHURRASCO_AMERICANO.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-barbecue-abacaxi","title":"Molho barbecue de abacaxi","category":"Molhos","description":"Barbecue frutado de abacaxi com shoyu, melado, mostarda e gengibre, reduzido em fogo baixo.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":1,"id":"1","name":"páprica defumada","unit":"tsp"},{"amount":1,"id":"2","name":"dente de alho picado","unit":""},{"amount":2,"id":"3","name":"copos de abacaxi sem miolo, picado","unit":""},{"amount":2,"id":"4","name":"vinagre","unit":"tbsp"},{"amount":4,"id":"5","name":"shoyu","unit":"tbsp"},{"amount":4,"id":"6","name":"melado (ou açúcar mascavo)","unit":"tbsp"},{"amount":2,"id":"7","name":"mostarda","unit":"tbsp"},{"amount":1,"id":"8","name":"manjericão fresco","unit":"pinch"},{"amount":500,"id":"9","name":"água","unit":"ml"},{"amount":"","id":"10","name":"gengibre a gosto","unit":""}],"steps":[{"content":"Coloque tudo numa panela e deixe reduzir em fogo baixo por 30 a 40 minutos.","timer":2100,"title":"Reduzir"}],"notes":"Receita do Bela Cozinha (GNT). Se quiser liso, bata no final.","images":[],"source":"Molhos.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-barbecue-texas","title":"Molho barbecue estilo Texas","category":"Molhos","description":"Barbecue de panela com extrato de tomate, mascavo, vinagre de maçã, páprica defumada e semente de mostarda.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":1,"id":"1","name":"azeite","unit":"tbsp"},{"amount":0.5,"id":"2","name":"cebola em pedaços grandes","unit":""},{"amount":3,"id":"3","name":"dentes de alho em pedaços grandes","unit":""},{"amount":0.5,"id":"4","name":"açúcar mascavo","unit":"cup"},{"amount":1,"id":"5","name":"extrato de tomate","unit":"cup"},{"amount":0.333,"id":"6","name":"vinagre de maçã","unit":"cup"},{"amount":1,"id":"7","name":"páprica defumada","unit":"tsp"},{"amount":1,"id":"8","name":"semente de mostarda","unit":"tsp"},{"amount":0.5,"id":"9","name":"pimenta-do-reino moída","unit":"tsp"},{"amount":1,"id":"10","name":"sal","unit":"tsp"},{"amount":2,"id":"11","name":"molho inglês","unit":"tbsp"}],"steps":[{"content":"Em fogo médio, frite a cebola no azeite até ficar transparente.","timer":0,"title":"Cebola"},{"content":"Junte o alho e frite até a cebola começar a dourar.","timer":0,"title":"Alho"},{"content":"Junte o açúcar e mexa até derreter completamente, cerca de 2 minutos.","timer":120,"title":"Açúcar"},{"content":"Junte o vinagre, o extrato, a páprica, a mostarda, a pimenta e o sal. Mexa até engrossar, cerca de 3 minutos.","timer":180,"title":"Engrossar"},{"content":"Adicione o molho inglês e mexa por mais 1 minuto.","timer":60,"title":"Molho inglês"},{"content":"Desligue e bata no liquidificador ou mixer em velocidade alta por cerca de 1 minuto, até ficar alaranjado.","timer":60,"title":"Bater"}],"notes":"Em pote bem fechado, dura até 1 mês na geladeira.","images":[],"source":"Molho_Barbecure_1.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-bearnaise","title":"Molho béarnaise","category":"Molhos","description":"Molho emulsionado de gemas, manteiga e redução de vinagre com estragão. Para carnes grelhadas, peixe e legumes.","servings":4,"yieldLabel":"porções","scale":true,"ingredients":[{"amount":2,"id":"1","name":"estragão picado (+ para decorar)","unit":"tsp"},{"amount":2,"id":"2","name":"cebola roxa picada","unit":"tsp"},{"amount":5,"id":"3","name":"vinagre de vinho branco","unit":"tbsp"},{"amount":4,"id":"4","name":"gemas","unit":""},{"amount":1,"id":"5","name":"suco de limão-siciliano","unit":"tbsp"},{"amount":1,"id":"6","name":"sal","unit":"pinch"},{"amount":225,"id":"7","name":"manteiga derretida","unit":"g"}],"steps":[{"content":"Cozinhe o estragão, a cebola e o vinagre em fogo médio por 5 minutos, até sobrar cerca de 1 colher de sopa. Coe e reserve o vinagre.","timer":300,"title":"Reduzir"},{"content":"Bata as gemas no liquidificador com o vinagre reduzido, o limão e o sal. Com o liquidificador ligado, junte a manteiga derretida aos poucos.","timer":0,"title":"Emulsionar"},{"content":"Transfira para uma vasilha, decore com estragão e sirva logo.","timer":0,"title":"Servir"}],"notes":"","images":[],"source":"Molhos.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-bechamel","title":"Molho bechamel","category":"Molhos","description":"Molho-mãe francês: roux de manteiga e farinha com leite aromatizado pela cebola piquée e noz-moscada. Base para lasanha, gratinados, croquete e molho mornay.","servings":1,"yieldLabel":"receita (~400 ml)","scale":true,"ingredients":[{"amount":16,"id":"1","name":"manteiga","unit":"g"},{"amount":16,"id":"2","name":"farinha de trigo","unit":"g"},{"amount":400,"id":"3","name":"leite integral","unit":"ml"},{"amount":"","id":"4","name":"## Cebola piquée","unit":""},{"amount":0.5,"id":"5","name":"cebola pequena (metade, sem casca)","unit":""},{"amount":1,"id":"6","name":"folha de louro","unit":""},{"amount":2,"id":"7","name":"cravos-da-índia","unit":""},{"amount":"","id":"8","name":"## Tempero","unit":""},{"amount":1,"id":"9","name":"noz-moscada ralada na hora","unit":"pinch"},{"amount":0.5,"id":"10","name":"sal","unit":"tsp"},{"amount":1,"id":"11","name":"pimenta-do-reino branca moída (opcional)","unit":"pinch"}],"steps":[{"content":"Prenda a folha de louro na face cortada da cebola, espetando os cravos através dela, como alfinetes.","timer":0,"title":"Montar a cebola piquée"},{"content":"Aqueça {3} com a cebola piquée em fogo baixo até quase ferver. Desligue, tampe e deixe em infusão.","timer":900,"title":"Aromatizar o leite"},{"content":"Em outra panela de fundo grosso, derreta {1} em fogo baixo, junte {2} de uma vez e mexa com batedor de arame por 1–2 minutos, até cheirar a biscoito, sem deixar dourar (roux branco).","timer":90,"title":"Fazer o roux"},{"content":"Retire a cebola do leite e reserve-a. Despeje o leite morno sobre o roux aos poucos, batendo sem parar para não empelotar. Devolva a cebola piquée à panela.","timer":0,"title":"Juntar o leite"},{"content":"Cozinhe em fogo baixo, mexendo de vez em quando, até engrossar e perder o gosto de farinha crua. Deve cobrir as costas de uma colher.","timer":600,"title":"Cozinhar"},{"content":"Retire a cebola piquée. Tempere com {10}, {9} e, se quiser, {11}. Se tiver grumos, passe pela peneira.","timer":0,"title":"Temperar e finalizar"}],"notes":"Consistência: com 16 g de manteiga e 16 g de farinha para 400 ml, o molho fica leve, bom para lasanha e para regar. Para gratinados, use 20 g de cada; para massa de croquete, 30–35 g de cada. Pimenta-do-reino branca é a clássica, porque não deixa pontinhos pretos. Para guardar, cubra com filme encostando no molho para não formar película; reaqueça mexendo, com um pouco de leite. Vira molho mornay com 50 g de queijo gruyère ou parmesão ralado no final.","images":[],"source":"","updatedAt":"2026-11-09T03:05:00.000Z"},{"id":"molho-bloom","title":"Molho bloom (para cebola empanada)","category":"Molhos","description":"Molho simples de maionese e ketchup com páprica e orégano, para a cebola florida.","servings":1,"yieldLabel":"porção","scale":true,"ingredients":[{"amount":1,"id":"1","name":"maionese","unit":"tbsp"},{"amount":0.5,"id":"2","name":"ketchup","unit":"tbsp"},{"amount":"","id":"3","name":"sal a gosto","unit":""},{"amount":"","id":"4","name":"pimenta-do-reino moída a gosto","unit":""},{"amount":"","id":"5","name":"páprica doce a gosto","unit":""},{"amount":"","id":"6","name":"orégano seco a gosto","unit":""}],"steps":[{"content":"Misture tudo e ajuste os temperos.","timer":0,"title":"Misturar"}],"notes":"","images":[],"source":"Molhos.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-blue-cheese","title":"Molho blue cheese","category":"Molhos","description":"Creme de leite batido com gorgonzola ou roquefort e um toque de vinagre.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":1,"id":"1","name":"lata de creme de leite com soro","unit":""},{"amount":200,"id":"2","name":"gorgonzola ou roquefort","unit":"g"},{"amount":1,"id":"3","name":"vinagre de vinho branco","unit":"tbsp"}],"steps":[{"content":"Bata tudo no liquidificador ou mixer e acerte o sal.","timer":0,"title":"Bater"}],"notes":"","images":[],"source":"Molhos.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-caesar","title":"Molho caesar","category":"Molhos","description":"Maionese, parmesão, anchova, alho e limão, batidos e descansados para apurar.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":1,"id":"1","name":"maionese","unit":"cup"},{"amount":1,"id":"2","name":"ovo","unit":""},{"amount":1,"id":"3","name":"parmesão ralado fino na hora","unit":"cup"},{"amount":2,"id":"4","name":"água","unit":"tbsp"},{"amount":2,"id":"5","name":"azeite","unit":"tbsp"},{"amount":0.5,"id":"6","name":"suco de limão","unit":"tbsp"},{"amount":1,"id":"7","name":"pasta de anchova","unit":"tbsp"},{"amount":2,"id":"8","name":"dentes de alho amassados","unit":""},{"amount":2,"id":"9","name":"açúcar","unit":"tsp"},{"amount":0.5,"id":"10","name":"pimenta-do-reino","unit":"tsp"},{"amount":0.25,"id":"11","name":"sal","unit":"tsp"},{"amount":0.25,"id":"12","name":"salsa desidratada","unit":"tsp"}],"steps":[{"content":"Bata tudo na batedeira e transfira para um pote.","timer":0,"title":"Bater"},{"content":"Deixe descansar algumas horas na geladeira para apurar o sabor.","timer":0,"title":"Descansar"}],"notes":"Use parmesão de peça ralado na hora: o de saquinho é muito salgado. Pasta de anchova caseira: bata anchovas em conserva no liquidificador e passe na peneira. O molho leva ovo cru.","images":[],"source":"Molhos.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-de-cafe","title":"Molho de café","category":"Molhos","description":"Molho rápido de manteiga, café forte, mostarda e limão para pincelar carnes. Fica pronto em 15 minutos.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":2,"id":"1","name":"molho inglês","unit":"tsp"},{"amount":0.333,"id":"2","name":"manteiga com sal","unit":"cup"},{"amount":1.5,"id":"3","name":"mostarda","unit":"tsp"},{"amount":1,"id":"4","name":"suco de limão","unit":"tbsp"},{"amount":1,"id":"5","name":"açúcar","unit":"tsp"},{"amount":1,"id":"6","name":"sal","unit":"pinch"},{"amount":"","id":"7","name":"molho de pimenta ou pimenta moída a gosto","unit":""},{"amount":0.667,"id":"8","name":"café forte pronto, sem açúcar","unit":"cup"}],"steps":[{"content":"Junte todos os ingredientes numa panela e aqueça mexendo até a manteiga derreter por completo.","timer":0,"title":"Aquecer"},{"content":"Pincele a carne antes de assar, cozinhe junto com ela ou sirva sobre a carne pronta.","timer":0,"title":"Usar"}],"notes":"Combina com lombo e filé mignon. Para massas (raviólis): acrescente 2 dentes de alho picados, 100 ml de creme de leite e cogumelos.","images":[],"source":"Molho_de_Cafe.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-vinagre-jacks","title":"Molho de vinagre Jack's Old South","category":"Molhos","description":"Molho fino de vinagre de cidra com ketchup, páprica e pimentas, estilo competição. Dura meses na geladeira.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":2,"id":"1","name":"vinagre de cidra","unit":"cup"},{"amount":3,"id":"2","name":"ketchup","unit":"tbsp"},{"amount":2,"id":"3","name":"páprica","unit":"tbsp"},{"amount":2,"id":"4","name":"açúcar mascavo","unit":"tbsp"},{"amount":4,"id":"5","name":"sal kosher","unit":"tsp"},{"amount":1,"id":"6","name":"molho de pimenta","unit":"tbsp"},{"amount":1,"id":"7","name":"pimenta-caiena (1 a 2)","unit":"tsp"},{"amount":1,"id":"8","name":"pimenta-do-reino moída (1 a 2)","unit":"tsp"}],"steps":[{"content":"Numa tigela não reativa, misture tudo até o açúcar e o sal dissolverem. Prove e ajuste a pimenta.","timer":0,"title":"Misturar"},{"content":"Transfira para um frasco limpo e esterilizado e guarde na geladeira.","timer":0,"title":"Guardar"}],"notes":"Dura vários meses na geladeira. A receita original fala só \"2 colheres de açúcar mascavo\": considerei colheres de sopa.","images":[],"source":"BBB_Temperos_Miron_Mixon.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-espanhol","title":"Molho espanhol (espagnole)","category":"Molhos","description":"Molho-mãe escuro: fundo escuro engrossado com roux escuro, mirepoix e tomate. Base do demi-glace.","servings":1,"yieldLabel":"receita (~750 ml)","scale":true,"ingredients":[{"amount":1,"id":"1","name":"fundo escuro quente","unit":"l"},{"amount":60,"id":"2","name":"manteiga","unit":"g"},{"amount":60,"id":"3","name":"farinha de trigo","unit":"g"},{"amount":"","id":"4","name":"## Mirepoix","unit":""},{"amount":100,"id":"5","name":"cebola em cubos pequenos","unit":"g"},{"amount":50,"id":"6","name":"cenoura em cubos pequenos","unit":"g"},{"amount":50,"id":"7","name":"aipo em cubos pequenos","unit":"g"},{"amount":"","id":"8","name":"## Sabor","unit":""},{"amount":30,"id":"9","name":"extrato de tomate","unit":"g"},{"amount":1,"id":"10","name":"folha de louro","unit":""},{"amount":1,"id":"11","name":"ramo de tomilho","unit":""},{"amount":5,"id":"12","name":"talos de salsinha","unit":""}],"steps":[{"content":"Derreta {2} e doure o mirepoix em fogo médio.","timer":480,"title":"Dourar o mirepoix"},{"content":"Polvilhe {3} e cozinhe mexendo em fogo baixo até ficar cor de avelã escura.","timer":600,"title":"Roux escuro"},{"content":"Junte {9} e mexa por 1–2 minutos.","timer":90,"title":"Tomate"},{"content":"Junte {1} aos poucos, batendo para não empelotar. Acrescente as ervas.","timer":0,"title":"Juntar o fundo"},{"content":"Cozinhe em fogo baixo por 1 hora a 1h30, retirando a espuma e a gordura, até reduzir para cerca de 750 ml.","timer":4500,"title":"Apurar"},{"content":"Passe pela peneira fina, pressionando de leve os legumes.","timer":0,"title":"Coar"}],"notes":"Clássico de Escoffier, raramente servido puro: é a base do demi-glace. Guarde coberto com filme encostando no molho.","images":[],"source":"","updatedAt":"2026-11-09T03:10:00.000Z"},{"id":"molho-ferrugem","title":"Molho ferrugem","category":"Molhos","description":"Molho escuro clássico com roux, legumes, bacon e caldo de carne, para lagarto e carne de panela. Pode congelar.","servings":1,"yieldLabel":"xícara","scale":true,"ingredients":[{"amount":2,"id":"1","name":"bacon picado","unit":"tbsp"},{"amount":1,"id":"2","name":"cebola picada","unit":""},{"amount":1,"id":"3","name":"talo de salsão picado","unit":""},{"amount":0.25,"id":"4","name":"cogumelos picados","unit":"cup"},{"amount":1,"id":"5","name":"cenoura pequena em rodelas","unit":""},{"amount":3,"id":"6","name":"manteiga","unit":"tbsp"},{"amount":3,"id":"7","name":"farinha de trigo","unit":"tbsp"},{"amount":1.25,"id":"8","name":"caldo de carne","unit":"cup"},{"amount":3,"id":"9","name":"salsinha picada","unit":"tbsp"},{"amount":2,"id":"10","name":"extrato de tomate","unit":"tsp"},{"amount":1,"id":"11","name":"tomate sem pele e sem sementes","unit":""},{"amount":1,"id":"12","name":"folha de louro","unit":""},{"amount":"","id":"13","name":"sal e pimenta-do-reino a gosto","unit":""}],"steps":[{"content":"Derreta a manteiga e cozinhe o bacon e os legumes por 10 minutos, mexendo, até dourarem levemente.","timer":600,"title":"Dourar"},{"content":"Abaixe o fogo, junte a farinha e cozinhe mexendo até ficar quase marrom.","timer":0,"title":"Roux"},{"content":"Fora do fogo, junte o caldo aos poucos. Volte ao fogo e mexa até engrossar.","timer":0,"title":"Caldo"},{"content":"Junte o restante, menos sal e pimenta. Tampe e cozinhe em fogo baixo por 45 minutos a 1 hora, mexendo às vezes e tirando a gordura que subir.","timer":3000,"title":"Apurar"},{"content":"Coe para outra panela e tempere com sal e pimenta. Reaqueça antes de servir.","timer":0,"title":"Coar e temperar"}],"notes":"","images":[],"source":"Molhos.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-ranch","title":"Molho ranch","category":"Molhos","description":"Maionese com creme azedo (ou iogurte) e ervas desidratadas. Descansa 30 minutos na geladeira.","servings":1,"yieldLabel":"receita","scale":true,"ingredients":[{"amount":1,"id":"1","name":"maionese","unit":"cup"},{"amount":1,"id":"2","name":"creme azedo ou iogurte natural","unit":"cup"},{"amount":1,"id":"3","name":"cebolinha desidratada","unit":"tsp"},{"amount":1,"id":"4","name":"salsinha desidratada","unit":"tsp"},{"amount":0.5,"id":"5","name":"dill","unit":"tsp"},{"amount":1,"id":"6","name":"alho desidratado","unit":"tsp"},{"amount":1,"id":"7","name":"cebola desidratada","unit":"tsp"},{"amount":0.5,"id":"8","name":"sal (colher de café)","unit":"tsp"},{"amount":0.5,"id":"9","name":"pimenta-do-reino moída (colher de café)","unit":"tsp"}],"steps":[{"content":"Numa tigela, misture todos os ingredientes.","timer":0,"title":"Misturar"},{"content":"Tampe e leve à geladeira por 30 minutos antes de usar.","timer":1800,"title":"Descansar"}],"notes":"","images":[],"source":"Molhos.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"molho-satay","title":"Molho satay","category":"Molhos","description":"Molho de amendoim da Malásia e Tailândia: leite de coco, pasta de amendoim, shoyu e pimenta. Pronto em 10 minutos.","servings":12,"yieldLabel":"porções","scale":true,"ingredients":[{"amount":300,"id":"1","name":"leite de coco","unit":"ml"},{"amount":130,"id":"2","name":"pasta de amendoim crocante (½ xícara)","unit":"g"},{"amount":0.5,"id":"3","name":"cebola pequena ralada","unit":""},{"amount":1,"id":"4","name":"shoyu","unit":"tbsp"},{"amount":2,"id":"5","name":"açúcar mascavo","unit":"tsp"},{"amount":0.5,"id":"6","name":"pimenta calabresa em flocos","unit":"tsp"}],"steps":[{"content":"Junte tudo numa panela e mexa em fogo médio até ferver.","timer":300,"title":"Ferver"},{"content":"Retire do fogo e mantenha aquecido.","timer":0,"title":"Servir"}],"notes":"Rende cerca de 1 ½ xícara.","images":[],"source":"Molhos.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"mousse-de-chocolate","title":"Mousse de chocolate","category":"Doces","description":"Mousse clássica com chocolate meio amargo, creme de leite e claras em neve com açúcar.","servings":6,"yieldLabel":"porções","scale":true,"ingredients":[{"amount":200,"id":"1","name":"chocolate meio amargo picado","unit":"g"},{"amount":3,"id":"2","name":"ovos frescos, com gemas e claras separadas","unit":""},{"amount":200,"id":"3","name":"creme de leite (1 lata, sem soro)","unit":"g"},{"amount":3,"id":"4","name":"açúcar","unit":"tbsp"},{"amount":1,"id":"5","name":"sal","unit":"pinch"}],"steps":[{"content":"Derreta o chocolate em banho-maria ou no micro-ondas em intervalos de 30 segundos, mexendo entre eles. Deixe amornar.","timer":0,"title":"Derreter o chocolate"},{"content":"Misture o creme de leite ao chocolate morno e depois as gemas, uma a uma, até ficar liso e brilhante.","timer":0,"title":"Base"},{"content":"Bata as claras com a pitada de sal até espumar, junte o açúcar aos poucos e bata até picos macios e brilhantes.","timer":0,"title":"Claras em neve"},{"content":"Junte 1/3 das claras ao chocolate e misture para soltar a massa. Incorpore o restante com uma espátula, em movimentos de baixo para cima, sem bater, para não perder o ar.","timer":0,"title":"Incorporar"},{"content":"Distribua em taças ou numa travessa e leve à geladeira por pelo menos 4 horas.","timer":14400,"title":"Gelar"}],"notes":"Leva ovo cru: use ovos bem frescos (ou pasteurizados) e consuma em até 2 dias. Na Austrália, a \"lata de creme de leite\" equivale à Nestlé Reduced Cream (lata de 250 g) ou a 200 ml de thickened cream. O chocolate deve estar morno, não quente, para não cozinhar as gemas nem derreter as claras.","images":[],"source":"","updatedAt":"2026-11-09T03:10:00.000Z"},{"id":"pork-roll-copa-lombo","title":"Pork roll de copa lombo defumada","category":"Churrasco","description":"Copa lombo aberta em manta, recheada com maionese e dry rub, enrolada e defumada no pit smoker até 68 °C.","servings":1,"yieldLabel":"peça (~2,5 kg)","scale":false,"ingredients":[{"amount":2.5,"id":"1","name":"copa lombo com boa capa de gordura","unit":"kg"},{"amount":3,"id":"2","name":"maionese","unit":"tbsp"},{"amount":3,"id":"3","name":"dry rub suíno","unit":"tbsp"},{"amount":"","id":"4","name":"barbante culinário","unit":""},{"amount":"","id":"5","name":"## Sanduíche (opcional)","unit":""},{"amount":2,"id":"6","name":"fatias de pão de milho","unit":""},{"amount":"","id":"7","name":"manteiga e maionese","unit":""},{"amount":"","id":"8","name":"alface verde e roxa","unit":""},{"amount":1,"id":"9","name":"fatia de tomate","unit":""},{"amount":"","id":"10","name":"picles a gosto","unit":""},{"amount":1,"id":"11","name":"fatia generosa do pork roll","unit":""}],"steps":[{"content":"Abra a copa lombo em borboleta, formando uma manta.","timer":0,"title":"Abrir a peça"},{"content":"Misture a maionese com o rub e passe metade por dentro da carne.","timer":0,"title":"Temperar por dentro"},{"content":"Enrole bem apertado, amarre com barbante e passe o restante da mistura por fora.","timer":0,"title":"Enrolar"},{"content":"Leve ao pit smoker a 120 °C por cerca de 2 horas e meia, até 68 °C no centro.","timer":9000,"title":"Defumar"},{"content":"Retire e deixe descansar 30 minutos para a umidade voltar às extremidades.","timer":1800,"title":"Descansar"},{"content":"Passe manteiga no pão de milho, toste na chapa, passe maionese e monte com alface, tomate, picles e uma fatia generosa do pork roll.","timer":0,"title":"Sanduíche"}],"notes":"","images":[],"source":"Dry_Rub_Suino.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"preparacao-jantar-de-sushi","title":"Preparação de jantar de sushi","category":"Técnicas","description":"Cronograma do dia, como num restaurante: blocos de peixe prontos com antecedência, fatiar e montar só na hora de servir.","servings":3,"scale":false,"ingredients":[{"amount":"","id":"1","name":"blocos de peixe limpos (saku)","unit":""},{"amount":"","id":"2","name":"papel-toalha e filme plástico","unit":""},{"amount":"","id":"3","name":"prato de servir gelado","unit":""},{"amount":"","id":"4","name":"pano úmido para a lâmina","unit":""},{"amount":"","id":"5","name":"saco fechado para o nori cortado","unit":""}],"steps":[{"content":"Tire pele, espinhas e linha de sangue e corte os {1}. Embrulhe cada bloco em {2} e guarde na parte mais fria da geladeira. Kobujime também entra aqui.","timer":0,"title":"Manhã ou até 6 h antes: limpar o peixe"},{"content":"Prepare os molhos (ponzu, tarê, maionese picante), cebolinha, pepino e abacate em bastões (abacate com limão), gengibre e wasabi. Corte o nori em tiras para gunkan e guarde no {5}.","timer":0,"title":"2 h antes: acompanhamentos"},{"content":"Comece o arroz de sushi. Ele fica pronto e morno na hora de montar. Nunca leve à geladeira.","timer":0,"title":"1h30 antes: arroz"},{"content":"Faça os recheios picados de gunkan e jô e corte as tiras de salmão do jô. Tudo coberto na geladeira.","timer":0,"title":"30 min antes: recheios"},{"content":"Tire um bloco por vez da geladeira, fatie o sashimi e o nigiri e devolva o resto ao frio. Monte os nigiris, enrole os makis e deixe os gunkans por último, porque o nori amolece. Passe o {4} na lâmina entre um peixe e outro.","timer":0,"title":"Na hora: fatiar e montar"},{"content":"Arrume o sashimi no {3} e tire da geladeira 5–10 minutos antes de comer: gelado demais perde sabor. Peixe frio, arroz morno.","timer":0,"title":"Servir"}],"notes":"Fatiar 1 hora antes, se for preciso: fatias no prato gelado, papel-toalha levemente úmido por cima, filme plástico encostando no peixe, na parte mais fria da geladeira. Atum só na hora, porque escurece rápido. Segurança: peixe cru no máximo 2 horas fora da geladeira (1 hora no verão de Sydney); para servir aos poucos, monte o prato em etapas.","images":[],"updatedAt":"2026-11-02T09:55:00.000Z"},{"id":"prime-rib-steak-sauce","title":"Prime rib com steak sauce","category":"Churrasco","description":"Prime rib marinado em vinho branco e shoyu, assado longe da brasa e selado no final, com molho de cerveja escura e cogumelos.","servings":1,"yieldLabel":"peça","scale":true,"ingredients":[{"amount":1,"id":"1","name":"peça de prime rib","unit":""},{"amount":"","id":"2","name":"sal grosso","unit":""},{"amount":"","id":"3","name":"## Marinada","unit":""},{"amount":2,"id":"4","name":"dentes de alho amassados","unit":""},{"amount":500,"id":"5","name":"vinho branco seco","unit":"ml"},{"amount":1,"id":"6","name":"pimenta calabresa","unit":"pinch"},{"amount":2,"id":"7","name":"shoyu","unit":"tbsp"},{"amount":"","id":"8","name":"## Steak sauce","unit":""},{"amount":"","id":"9","name":"fio de azeite","unit":""},{"amount":100,"id":"10","name":"manteiga","unit":"g"},{"amount":2,"id":"11","name":"dentes de alho picados","unit":""},{"amount":1,"id":"12","name":"cebola em rodelas","unit":""},{"amount":355,"id":"13","name":"cerveja escura","unit":"ml"},{"amount":200,"id":"14","name":"cogumelos frescos","unit":"g"},{"amount":1,"id":"15","name":"sal","unit":"tsp"}],"steps":[{"content":"Tempere a carne com sal por todos os lados, coloque num saco com os ingredientes da marinada e deixe 1 hora.","timer":3600,"title":"Marinar"},{"content":"Coloque na parte mais alta da churrasqueira por 15 a 20 minutos.","timer":1080,"title":"Assar longe da brasa"},{"content":"Desça para perto do fogo e sele 2 minutos de cada lado.","timer":120,"title":"Selar"},{"content":"Deixe a carne descansar 3 minutos antes de fatiar.","timer":180,"title":"Descansar"},{"content":"Numa panela, aqueça o azeite e a manteiga, junte o alho, a cebola, a cerveja, os cogumelos e o sal. Cozinhe de 15 a 20 minutos.","timer":1080,"title":"Fazer o molho"}],"notes":"O tempo na grelha alta depende da espessura: para ponto malpassado, procure 52–54 °C no centro antes de selar.","images":[],"source":"CHURRASCO_AMERICANO.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"salmao-cortes","title":"Salmão: cortes para sashimi, nigiri e maki","category":"Técnicas","description":"Como transformar um corte central de salmão em blocos (saku) e fatiar para sashimi, nigiri e maki.","servings":3,"scale":false,"ingredients":[{"amount":400,"id":"1","name":"filé de salmão, corte central, próprio para sashimi","unit":"g"},{"amount":"","id":"2","name":"pinça de espinha","unit":""},{"amount":"","id":"3","name":"faca yanagiba bem afiada","unit":""},{"amount":"","id":"4","name":"pano úmido para a lâmina","unit":""}],"steps":[{"content":"Mantenha {1} embrulhado em papel-toalha e filme na parte mais fria da geladeira até a hora de cortar. Peixe frio fatia mais limpo.","timer":0,"title":"Gelar o peixe"},{"content":"Se tiver pele, passe a faca rente entre carne e pele. Passe o dedo na linha central e puxe as espinhas finas com {2}, no sentido da cabeça.","timer":0,"title":"Pele e espinhas"},{"content":"Corte ao longo da faixa de gordura branca que divide o filé. O lado com mais listras é a barriga (A); o mais vermelho e firme, o lombo (B).","timer":0,"title":"Separar barriga e lombo (1)"},{"content":"Apare as bordas finas para formar blocos retangulares. Guarde as aparas para tartar ou maki.","timer":0,"title":"Aparar (2)"},{"content":"Faca na vertical, fatias de ~1 cm atravessando as listras brancas, num único puxão do salto à ponta de {3}, sem serrar (hira-zukuri).","timer":0,"title":"Sashimi no lombo"},{"content":"Divida a barriga em tiras de ~3,5 cm no sentido das listras. Fatie cada tira atravessando as listras, faca inclinada ~45°, fatias de ~5 mm e 7–8 × 3 cm (sogi-giri).","timer":0,"title":"Nigiri na barriga"},{"content":"Se o bloco tiver mais de 1,5 cm de altura, fatie na horizontal em camadas de ~1 cm. Corte bastões no comprimento: 1 × 1 cm para hosomaki, 1,5 × 1 cm para uramaki, com ~19–20 cm.","timer":0,"title":"Bastões para maki"},{"content":"Passe {4} na lâmina a cada poucos cortes. Guarde as fatias cobertas na geladeira e sirva no mesmo dia.","timer":0,"title":"Lâmina limpa"}],"notes":"Regra de ouro: as listras de gordura ficam atravessadas na fatia, como faixas. Se ficarem no comprimento, o corte foi no sentido errado e a fatia se desfaz. Mapa do filé: lombo e barriga são ótimos para sashimi e nigiri; a cauda, mais fina e com mais nervos, vai melhor em tartar e maki; o kama (gola atrás da cabeça) é melhor grelhado. Retire sempre a linha de sangue (chiai), de gosto forte.","images":[{"src":"images/salmao-cortes/01.png","caption":"Mapa do filé: kama, lombo (se), barriga (harasu), cauda e a linha de sangue (chiai) entre lombo e barriga."},{"src":"images/salmao-cortes/02.jpg","caption":"Divisão do filé: barriga (A) para nigiri, lombo (B) para sashimi."},{"src":"images/salmao-cortes/03.jpg","caption":"Nigiri: tiras paralelas às listras, fatias atravessando."},{"src":"images/salmao-cortes/04.jpg","caption":"Maki: bastões no comprimento do bloco."}],"updatedAt":"2026-11-01T10:00:00.000Z"},{"id":"short-ribs-barbecue","title":"Short ribs com molho barbecue","category":"Churrasco","description":"Costela bovina com rub simples, assada longe do fogo e selada, com molho barbecue de uísque e fumaça.","servings":1,"yieldLabel":"peça","scale":true,"ingredients":[{"amount":1,"id":"1","name":"peça de short rib","unit":""},{"amount":2,"id":"2","name":"sal","unit":"tbsp"},{"amount":0.5,"id":"3","name":"pimenta-do-reino","unit":"tbsp"},{"amount":1,"id":"4","name":"alho em pó","unit":"tbsp"},{"amount":"","id":"5","name":"## Molho barbecue","unit":""},{"amount":1,"id":"6","name":"açúcar mascavo","unit":"cup"},{"amount":1,"id":"7","name":"extrato de tomate","unit":"cup"},{"amount":0.333,"id":"8","name":"vinagre de maçã","unit":"cup"},{"amount":1,"id":"9","name":"páprica picante","unit":"tsp"},{"amount":1,"id":"10","name":"alho em pó","unit":"tsp"},{"amount":1,"id":"11","name":"pimenta-caiena","unit":"tsp"},{"amount":1,"id":"12","name":"fumaça em pó","unit":"tsp"},{"amount":1,"id":"13","name":"dose de uísque","unit":""}],"steps":[{"content":"Misture o sal, a pimenta e o alho em pó e tempere a carne.","timer":0,"title":"Temperar"},{"content":"Coloque na churrasqueira, longe do fogo, por 1 hora.","timer":3600,"title":"Assar"},{"content":"Sele 5 minutos de cada lado.","timer":300,"title":"Selar"},{"content":"Derreta o açúcar mascavo numa panela, junte o extrato de tomate e misture. Adicione o restante, mexa bem e deixe mais 1 minuto no fogo.","timer":60,"title":"Fazer o molho"}],"notes":"","images":[],"source":"CHURRASCO_AMERICANO.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"snapper-cortes","title":"Snapper: cortes para sashimi e nigiri","category":"Técnicas","description":"Do filé de snapper aos blocos de lombo e barriga, com usuzukuri, nigiri e a opção de kobujime.","servings":3,"scale":false,"ingredients":[{"amount":2,"id":"1","name":"filés de snapper (de um peixe de ~1,2 kg)","unit":""},{"amount":1,"id":"2","name":"sal fino (para kobujime)","unit":"tsp"},{"amount":2,"id":"3","name":"folhas de kombu (opcional)","unit":""},{"amount":"","id":"4","name":"pinça de espinha","unit":""},{"amount":"","id":"5","name":"faca yanagiba bem afiada","unit":""}],"steps":[{"content":"Snapper é selvagem: para comer cru, congele {1} a -20 °C por 7 dias, ou confirme na peixaria que é próprio para sashimi. Descongele na geladeira.","timer":0,"title":"Segurança"},{"content":"Na aba fina da barriga, perto da cabeça, passe a faca rente por baixo das costelas e tire junto a membrana escura. Guarde para o caldo.","timer":0,"title":"Aparar as costelas (1)"},{"content":"Um corte de cada lado da linha vermelha central, em V, e retire a tira. O filé se divide em lombo (A) e barriga (B).","timer":0,"title":"Linha de sangue (2)"},{"content":"Passe o dedo na linha central e puxe as pontinhas com {4}, no sentido da cabeça. Acerte as bordas.","timer":0,"title":"Espinhas finas"},{"content":"Salgue os blocos de leve com {2}, espere, seque bem, envolva entre {3} umedecidas com água e embrulhe em filme. Geladeira por 3–6 horas.","timer":1500,"title":"Kobujime (opcional)"},{"content":"Usuzukuri: {5} bem inclinada, fatias quase transparentes em leque, com ponzu. Ou hira-zukuri, fatias de 5–8 mm num único puxão.","timer":0,"title":"Sashimi no lombo"},{"content":"Fatias diagonais de 5–8 mm, com ~7 × 3 cm. Fica ótimo maçaricado (aburi), com sal e raspas de limão.","timer":0,"title":"Nigiri na barriga"}],"notes":"Fiozinhos escuros e finos na carne geralmente são vasinhos sanguíneos. Algo enrolado e mais grosso que sai inteiro com a pinça: não coma cru. Matsukawa-zukuri: mantenha a pele, escalde com água fervente e mergulhe em água gelada antes de fatiar.","images":[{"src":"images/snapper-cortes/01.jpg","caption":"Lombo (A), barriga (B), costelas (1) e linha de sangue (2)."}],"updatedAt":"2026-11-01T09:50:00.000Z"},{"id":"t-bone-com-legumes","title":"T-bone com legumes grelhados","category":"Churrasco","description":"T-bone na grelha com legumes pincelados em azeite temperado com alho.","servings":2,"yieldLabel":"porções","scale":true,"ingredients":[{"amount":1,"id":"1","name":"bife de T-bone","unit":""},{"amount":"","id":"2","name":"sal, pimenta-do-reino e azeite","unit":""},{"amount":"","id":"3","name":"## Legumes","unit":""},{"amount":1,"id":"4","name":"cebola roxa fatiada","unit":""},{"amount":1,"id":"5","name":"cebola branca fatiada","unit":""},{"amount":1,"id":"6","name":"abobrinha fatiada","unit":""},{"amount":1,"id":"7","name":"berinjela fatiada","unit":""},{"amount":1,"id":"8","name":"cenoura fatiada","unit":""},{"amount":1,"id":"9","name":"tomate fatiado","unit":""},{"amount":"","id":"10","name":"azeite, sal, pimenta-do-reino e alho granulado","unit":""}],"steps":[{"content":"Tempere o T-bone, regue com azeite e grelhe 9 minutos de um lado e 6 do outro.","timer":540,"title":"Grelhar a carne"},{"content":"Misture azeite com sal, pimenta e alho granulado.","timer":0,"title":"Temperar o azeite"},{"content":"Pincele os legumes com o azeite temperado e leve à grelha até marcar.","timer":0,"title":"Grelhar os legumes"},{"content":"Sirva a carne com os legumes.","timer":0,"title":"Servir"}],"notes":"","images":[],"source":"CHURRASCO_AMERICANO.docx","updatedAt":"2026-11-09T03:00:00.000Z"},{"id":"tempura","title":"Tempura de camarão e legumes","category":"Frituras","description":"Massa leve e crocante feita com água com gás gelada, servida com molho tentsuyu de dashi, shoyu e mirin.","servings":4,"scale":true,"ingredients":[{"amount":12,"id":"1","name":"camarões grandes, descascados, com o rabo","unit":""},{"amount":400,"id":"2","name":"legumes em fatias (batata-doce, abóbora, berinjela, cogumelos, vagem)","unit":"g"},{"amount":120,"id":"3","name":"farinha de trigo fraca","unit":"g"},{"amount":1,"id":"4","name":"gema de ovo","unit":""},{"amount":200,"id":"5","name":"água com gás geladíssima","unit":"ml"},{"amount":1,"id":"6","name":"óleo para fritar","unit":"l"},{"amount":200,"id":"7","name":"dashi","unit":"ml"},{"amount":50,"id":"8","name":"shoyu","unit":"ml"},{"amount":50,"id":"9","name":"mirin","unit":"ml"},{"amount":4,"id":"10","name":"nabo daikon ralado","unit":"tbsp"}],"steps":[{"content":"Leve ao fogo {7}, {8} e {9} até ferver. Desligue e reserve morno.","timer":180,"title":"Fazer o tentsuyu"},{"content":"Faça 3–4 cortes rasos na barriga de {1} e pressione para ficarem retos. Seque bem os camarões e {2}.","timer":0,"title":"Preparar os camarões"},{"content":"Aqueça {6} em panela funda a 170–180 °C. Sem termômetro: uma gota de massa afunda um pouco e sobe logo, borbulhando.","timer":420,"title":"Aquecer o óleo"},{"content":"Misture {4} com {5}. Junte {3} de uma vez e mexa com hashi só alguns segundos. A massa deve ficar empelotada.","timer":0,"title":"Fazer a massa na hora"},{"content":"Passe cada peça numa leve camada de farinha, depois na massa, e frite poucas por vez até dourar bem claro. Legumes 2–3 min, camarão 1–2 min.","timer":150,"title":"Fritar"},{"content":"Escorra em grade ou papel-toalha e sirva na hora com o tentsuyu e {10} à parte.","timer":0,"title":"Servir"}],"notes":"Tudo bem gelado e massa pouco mexida: é isso que deixa crocante. Mantenha a tigela da massa sobre gelo. Farinha pronta de tempura (天ぷら粉) também funciona bem. Nunca deixe o óleo quente sem supervisão.","images":[],"updatedAt":"2026-11-01T09:50:00.000Z"},{"id":"tomahawk-batatas-bacon","title":"Tomahawk com batatas, queijo e bacon","category":"Churrasco","description":"Tomahawk assado na parte alta e selado, com batatas gratinadas na churrasqueira tampada.","servings":1,"yieldLabel":"peça","scale":true,"ingredients":[{"amount":1,"id":"1","name":"peça de tomahawk","unit":""},{"amount":2,"id":"2","name":"sal","unit":"tsp"},{"amount":0.5,"id":"3","name":"pimenta-do-reino","unit":"tsp"},{"amount":1,"id":"4","name":"alho granulado","unit":"tsp"},{"amount":"","id":"5","name":"azeite","unit":""},{"amount":"","id":"6","name":"## Batatas","unit":""},{"amount":6,"id":"7","name":"batatas assadas, cortadas ao meio","unit":""},{"amount":"","id":"8","name":"fatias de queijo a gosto","unit":""},{"amount":100,"id":"9","name":"bacon em cubos","unit":"g"},{"amount":"","id":"10","name":"cebolinha picada","unit":""}],"steps":[{"content":"Misture os temperos, tempere a carne e regue com azeite.","timer":0,"title":"Temperar"},{"content":"Leve à parte mais alta da churrasqueira por 20 a 30 minutos.","timer":1500,"title":"Assar"},{"content":"Sele 5 minutos de cada lado e deixe descansar 5 minutos fora do fogo.","timer":300,"title":"Selar e descansar"},{"content":"Numa panela rasa, coloque as batatas, o queijo por cima e o bacon. Leve à churrasqueira tampada por 10 minutos e finalize com cebolinha.","timer":600,"title":"Batatas"}],"notes":"","images":[],"source":"CHURRASCO_AMERICANO.docx","updatedAt":"2026-11-09T03:00:00.000Z"}],"videos":[{"id":"yt-kQnvT08HsS0","addedAt":"2026-11-01T10:20:01.000Z","category":"","note":"Sem título ainda: falta preencher título, categoria e nota.","title":"Vídeo do YouTube (kQnvT08HsS0)","url":"https://www.youtube.com/watch?v=kQnvT08HsS0"},{"id":"yt-R6dqQIn8SNk","addedAt":"2026-11-01T10:20:00.000Z","category":"","note":"Sem título ainda: falta preencher título, categoria e nota.","title":"Vídeo do YouTube (R6dqQIn8SNk)","url":"https://www.youtube.com/watch?v=R6dqQIn8SNk"}]};
